"use client";

import { cn } from "@/lib/utils";
import {
  diagramUnitStyle,
  horizontalDiagramMetrics,
} from "@/lib/tfl/line-diagram";
import {
  StraightRouteTrack,
  StraightStripStationColumn,
  type StraightStripStation,
  type StripLabelPlacement,
  type StripSegmentState,
} from "@/components/tfl/diagram/straight-strip-parts";
import { StraightStripFitted } from "@/components/tfl/diagram/straight-strip-fitted";
import type { RouteTrackStyle } from "@/lib/tfl/route-track";

export type { StraightStripStation, StripLabelPlacement, StripSegmentState };
export type { DiagramSegment, DiagramSegmentState } from "@/lib/tfl/diagram-station";

export {
  buildSegmentStateMap,
  isStationOutOfUse,
  stationOutOfUseFromSegments,
  selectFittedLabelIndexes,
  StraightRouteTrack,
  StraightStripStationColumn,
  HorizontalRouteStrip,
  HorizontalStationColumn,
  OUT_OF_USE_LINE_COLOR,
  resolveLabelSide,
} from "@/components/tfl/diagram/straight-strip-parts";

/** @deprecated Prefer `StraightStripStation`. */
export type { HorizontalDiagramStation } from "@/components/tfl/diagram/straight-strip-parts";
/** @deprecated Prefer `StripLabelPlacement`. */
export type { HorizontalLabelPlacement } from "@/components/tfl/diagram/straight-strip-parts";

export type StraightStripProps = {
  stations: readonly StraightStripStation[];
  /** Hex route colour. */
  lineColor: string;
  lineName?: string;
  /**
   * Absolute route line thickness in px (= unit x).
   * When omitted, uses `DIAGRAM_BASELINE.horizontal` × inherited
   * `--tfl-diagram-scale`.
   */
  x?: number;
  className?: string;
  /** Prepared adjacent segment states (length = stations.length - 1). */
  segmentStates?: readonly StripSegmentState[];
  /** Prepared per-station out-of-use flags. */
  stationOutOfUse?: readonly boolean[];
  /**
   * Fit the full route into the container width with no horizontal scroll.
   * Left-aligned fixed pitch; scales the strip uniformly. Opt-in.
   */
  fit?: boolean;
  /** Station IDs that must keep a visible label when `fit` is on. */
  forceLabelIds?: readonly string[];
  /**
   * Shared fit scale for a group of fitted strips so pitch and type match
   * across lines (homepage week-ahead). Ignored unless `fit` is true.
   */
  sharedFitScale?: number;
  /**
   * Station name position relative to the route.
   * `alternate` reserves both bands so markers stay aligned.
   */
  labelPlacement?: StripLabelPlacement;
  /**
   * Route paint: solid (default), Overground/Elizabeth parallel, or cable-car
   * triple. Pass explicitly — this atom does not look up TfL ids.
   */
  trackStyle?: RouteTrackStyle;
};

/**
 * Atomic straight strip: render prepared stations / segment states only.
 * No TfL colour lookup, adjacency inference, or label recipes —
 * pass a prepared model from `LineStrip` / `prepareStraightStrip`.
 */
export const StraightStrip = ({
  stations,
  lineColor,
  lineName,
  x,
  className,
  segmentStates: segmentStatesProp,
  stationOutOfUse: stationOutOfUseProp,
  fit = false,
  forceLabelIds,
  sharedFitScale,
  labelPlacement = "above",
  trackStyle = "solid",
}: StraightStripProps) => {
  if (stations.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">No stations to display.</p>
    );
  }

  const segmentStates =
    segmentStatesProp ??
    Array.from({ length: Math.max(0, stations.length - 1) }, () => "normal" as const);
  const stationOutOfUse =
    stationOutOfUseProp ?? stations.map(() => false);

  if (fit) {
    return (
      <StraightStripFitted
        stations={stations}
        lineColor={lineColor}
        lineName={lineName}
        x={x}
        className={className}
        segmentStates={segmentStates}
        stationOutOfUse={stationOutOfUse}
        forceLabelIds={forceLabelIds}
        sharedFitScale={sharedFitScale}
        labelPlacement={labelPlacement}
        trackStyle={trackStyle}
      />
    );
  }

  const m = horizontalDiagramMetrics(labelPlacement);
  const maxConnections = stations.reduce(
    (n, s) =>
      Math.max(
        n,
        (s.connections ?? []).filter((c) => c.id !== "national-rail").length,
      ),
    0,
  );
  const connectionBand =
    maxConnections > 0
      ? `calc(${m.flagHeight} * ${maxConnections})`
      : undefined;
  const totalWidth = `calc(${m.colWidth} * ${stations.length})`;

  return (
    <div
      className={cn("w-max min-w-0", className)}
      style={diagramUnitStyle("horizontal", x)}
    >
      {lineName ? (
        <div className="mb-3">
          <span
            className="inline-block px-2.5 py-1 font-semibold text-white"
            style={{ backgroundColor: lineColor, fontSize: m.titleSize }}
          >
            {lineName}
          </span>
        </div>
      ) : null}

      <div className="relative" style={{ width: totalWidth }}>
        <StraightRouteTrack
          stationCount={stations.length}
          segmentStates={segmentStates}
          lineColor={lineColor}
          lineTop={m.lineTop}
          lineWidth={m.lineWidth}
          colWidthUnits={m.colWidthUnits}
          trackStyle={trackStyle}
        />

        <ol className="relative m-0 flex list-none items-start p-0">
          {stations.map((station, index) => (
            <StraightStripStationColumn
              key={`${station.id}-${index}`}
              station={station}
              index={index}
              lineColor={lineColor}
              showLabel
              connectionBand={connectionBand}
              colWidth={m.colWidth}
              outOfUse={stationOutOfUse[index] ?? false}
              labelPlacement={labelPlacement}
            />
          ))}
        </ol>
      </div>
    </div>
  );
};

"use client";

import { cn } from "@/lib/utils";
import { horizontalDiagramMetrics, ux } from "@/lib/tfl/line-diagram";
import { formatStationName } from "@/lib/tfl/diagram-station";
import { StationName } from "@/components/tfl/station-name";
import { NationalRailPictogram } from "@/components/tfl/national-rail-pictogram";
import {
  routeTrackHeightUnits,
  routeTrackRailCount,
  type RouteTrackStyle,
} from "@/lib/tfl/route-track";
import {
  buildSegmentStateMap,
  isStationOutOfUse,
  stationOutOfUseFromSegments,
  type StraightStripStation,
  type StripLabelPlacement,
  type StripSegmentState,
} from "@/lib/tfl/strip-model";

export type {
  StraightStripStation,
  StripLabelPlacement,
  StripSegmentState,
} from "@/lib/tfl/strip-model";

/** @deprecated Prefer `StraightStripStation`. */
export type HorizontalDiagramStation = StraightStripStation;
/** @deprecated Prefer `StripLabelPlacement`. */
export type HorizontalLabelPlacement = StripLabelPlacement;

export {
  buildSegmentStateMap,
  isStationOutOfUse,
  stationOutOfUseFromSegments,
};

/**
 * Closed / out-of-use solid — lighter than Jubilee (#838D93).
 * Uses theme `--muted` (≈ Tailwind zinc-100 / oklch 0.97 in light mode).
 */
export const OUT_OF_USE_LINE_COLOR = "var(--muted)";

export const resolveLabelSide = (
  index: number,
  placement: StripLabelPlacement,
): "above" | "below" => {
  if (placement === "above") return "above";
  if (placement === "below") return "below";
  return index % 2 === 0 ? "above" : "below";
};

type RouteStripProps = {
  stationCount: number;
  segmentStates: readonly StripSegmentState[];
  lineColor: string;
  /** Top of a 1× solid route (centreline − 0.5×). Multi-rail stacks re-centre. */
  lineTop: string;
  /** Solid-route height (1×). Ignored for parallel / cable-car stacks. */
  lineWidth: string;
  colWidthUnits: number;
  /** Explicit paint style — primitives never infer from TfL ids. */
  trackStyle?: RouteTrackStyle;
};

const SegmentPaint = ({
  color,
  trackStyle,
}: {
  color: string;
  trackStyle: RouteTrackStyle;
}) => {
  if (trackStyle === "solid") {
    return <div className="h-full w-full" style={{ backgroundColor: color }} />;
  }

  const rails = routeTrackRailCount(trackStyle);
  // stroke === gap === 0.33× — equal flex bands keep §5 proportions.
  const bands: { key: string; fill?: string }[] = [];
  for (let i = 0; i < rails; i += 1) {
    bands.push({ key: `rail-${i}`, fill: color });
    if (i < rails - 1) {
      bands.push({ key: `gap-${i}` });
    }
  }

  return (
    <div className="flex h-full w-full flex-col">
      {bands.map((band) => (
        <div
          key={band.key}
          className="min-h-0 w-full flex-1"
          style={{ backgroundColor: band.fill }}
        />
      ))}
    </div>
  );
};

/** Solid / parallel / cable-car / out-of-use segments on the route centreline. */
export const StraightRouteTrack = ({
  stationCount,
  segmentStates,
  lineColor,
  lineTop,
  lineWidth,
  colWidthUnits,
  trackStyle = "solid",
}: RouteStripProps) => {
  if (stationCount < 2) return null;

  const heightUnits = routeTrackHeightUnits(trackStyle);
  // Solid metrics pass top = centre − 0.5×; re-centre taller / shorter stacks.
  const top =
    trackStyle === "solid"
      ? lineTop
      : `calc(${lineTop} + ${ux(0.5)} - ${ux(heightUnits / 2)})`;
  const height = trackStyle === "solid" ? lineWidth : ux(heightUnits);

  return (
    <div
      aria-hidden
      className="pointer-events-none absolute inset-x-0"
      style={{ top, height }}
    >
      {segmentStates.map((state, index) => {
        const left = `calc(${ux(colWidthUnits)} * ${index + 0.5})`;
        const width = ux(colWidthUnits);
        const color =
          state === "out-of-use" ? OUT_OF_USE_LINE_COLOR : lineColor;

        return (
          <div
            key={`seg-${index}`}
            className="absolute top-0"
            style={{ left, width, height }}
          >
            <SegmentPaint color={color} trackStyle={trackStyle} />
          </div>
        );
      })}
    </div>
  );
};

/** @deprecated Prefer `StraightRouteTrack`. */
export const HorizontalRouteStrip = StraightRouteTrack;

type StationColumnProps = {
  station: StraightStripStation;
  index: number;
  lineColor: string;
  showLabel: boolean;
  connectionBand?: string;
  /** Fixed column width (CSS length). */
  colWidth: string;
  /** Closed for this line — tick/ring use the out-of-use colour. */
  outOfUse?: boolean;
  /** Where station names sit relative to the route. */
  labelPlacement?: StripLabelPlacement;
};

export const StraightStripStationColumn = ({
  station,
  index,
  lineColor,
  showLabel,
  connectionBand,
  colWidth,
  outOfUse = false,
  labelPlacement = "above",
}: StationColumnProps) => {
  const m = horizontalDiagramMetrics();
  const isInterchange = Boolean(station.interchange);
  const connections = (station.connections ?? []).filter(
    (c) => c.id !== "national-rail",
  );
  const markerColor = outOfUse ? OUT_OF_USE_LINE_COLOR : lineColor;
  const accessibleName = formatStationName(station.name);
  const labelSide = resolveLabelSide(index, labelPlacement);
  const reserveAbove =
    labelPlacement === "above" || labelPlacement === "alternate";
  const reserveBelow =
    labelPlacement === "below" || labelPlacement === "alternate";
  const showAbove = showLabel && labelSide === "above";
  const showBelow = showLabel && labelSide === "below";

  const nameBand = (visible: boolean, alignEnd: boolean) => (
    <div
      className={cn(
        "relative flex w-full justify-center px-0.5 text-center",
        alignEnd ? "items-end" : "items-start",
      )}
      style={{ height: m.nameBand }}
      aria-hidden={visible ? undefined : true}
    >
      {visible ? (
        <div className="relative inline-flex max-w-full flex-col items-center">
          <StationName
            name={station.name}
            lines={station.labelLines}
            layout="auto"
            accessibleName={accessibleName}
            maxLines={2}
            allowScaleDown={false}
            align="center"
            className="font-medium text-foreground"
            style={{
              fontSize: m.nameSize,
              lineHeight: 1.15,
            }}
          />
          {station.nationalRail ? (
            <span
              className="pointer-events-none absolute bottom-0 left-full ml-0.5 flex items-end"
              title="National Rail"
            >
              <NationalRailPictogram height="0.7em" />
            </span>
          ) : null}
          {station.nationalRail ? (
            <span className="sr-only">National Rail</span>
          ) : null}
        </div>
      ) : null}
    </div>
  );

  const marker = (
    <div
      className="relative z-10 flex items-center justify-center"
      style={{
        marginTop: reserveAbove ? m.nameGap : 0,
        width: colWidth,
        height: m.markerBand,
      }}
    >
      {isInterchange ? (
        <span
          className={cn(
            "box-border block rounded-full",
            !outOfUse && "bg-white",
          )}
          style={{
            width: m.ringOuter,
            height: m.ringOuter,
            borderWidth: m.ringStroke,
            borderStyle: "solid",
            borderColor: outOfUse ? OUT_OF_USE_LINE_COLOR : "#000",
            backgroundColor: outOfUse ? OUT_OF_USE_LINE_COLOR : undefined,
          }}
          aria-hidden
        />
      ) : (
        <span
          className="block"
          style={{
            width: m.tickWidth,
            height: m.tickHeight,
            backgroundColor: markerColor,
          }}
          aria-hidden
        />
      )}
    </div>
  );

  const flags =
    connections.length > 0 && showLabel ? (
      <div
        className="inline-flex max-w-full flex-col overflow-hidden"
        style={{
          marginTop: m.flagClearance,
          minHeight: connectionBand,
        }}
        aria-label={`Connections: ${connections.map((c) => c.name).join(", ")}`}
      >
        {connections.map((c) => (
          <span
            key={`${station.id}-${c.id}`}
            className="flex w-full items-center justify-center px-1.5 leading-none font-medium whitespace-nowrap"
            style={{
              backgroundColor: c.color ?? "#64748b",
              color: c.darkText ? "#0019A8" : "#fff",
              height: m.flagHeight,
              minWidth: m.flagMinWidth,
              fontSize: m.flagFont,
            }}
          >
            {c.name}
          </span>
        ))}
      </div>
    ) : (
      <div
        aria-hidden
        style={{
          marginTop: m.flagClearance,
          minHeight: connectionBand,
        }}
      />
    );

  return (
    <li
      className="relative flex shrink-0 flex-col items-center"
      style={{ width: colWidth }}
    >
      {!showLabel ? <span className="sr-only">{accessibleName}</span> : null}
      {reserveAbove ? nameBand(showAbove, true) : null}
      {marker}
      {reserveBelow ? (
        <div style={{ marginTop: m.nameGap }}>{nameBand(showBelow, false)}</div>
      ) : null}
      {flags}
    </li>
  );
};

/** @deprecated Prefer `StraightStripStationColumn`. */
export const HorizontalStationColumn = StraightStripStationColumn;

/**
 * Choose which station indexes show a visible label in fitted mode.
 * Always terminals + forced IDs; prefer interchanges when space allows.
 */
export const selectFittedLabelIndexes = (
  stations: readonly StraightStripStation[],
  availableWidthPx: number,
  forceLabelIds: readonly string[] = [],
  colWidthPx?: number,
): Set<number> => {
  const n = stations.length;
  const show = new Set<number>();
  if (n === 0) return show;

  show.add(0);
  show.add(n - 1);

  const forced = new Set(forceLabelIds);
  stations.forEach((station, index) => {
    if (forced.has(station.id)) show.add(index);
  });

  const pitch = colWidthPx && colWidthPx > 0 ? colWidthPx : 56;
  const budget = Math.max(2, Math.floor(availableWidthPx / pitch));
  if (show.size >= budget) return show;

  const interchangeIndexes = stations
    .map((station, index) => (station.interchange ? index : -1))
    .filter((index) => index > 0 && index < n - 1);

  for (const index of interchangeIndexes) {
    if (show.size >= budget) break;
    show.add(index);
  }

  if (show.size >= budget) return show;

  const remaining = budget - show.size;
  if (remaining > 0 && n > 2) {
    const step = n / (remaining + 1);
    for (let i = 1; i <= remaining; i += 1) {
      const index = Math.min(n - 2, Math.max(1, Math.round(step * i)));
      show.add(index);
      if (show.size >= budget) break;
    }
  }

  return show;
};

"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import {
  DIAGRAM_BASELINE,
  DIAGRAM_SCALE_VAR,
  DIAGRAM_X_VAR,
  horizontalDiagramMetrics,
} from "@/lib/tfl/line-diagram";
import {
  StraightRouteTrack,
  StraightStripStationColumn,
  selectFittedLabelIndexes,
  type StraightStripStation,
  type StripLabelPlacement,
  type StripSegmentState,
} from "@/components/tfl/diagram/straight-strip-parts";
import type { RouteTrackStyle } from "@/lib/tfl/route-track";

type FittedProps = {
  stations: readonly StraightStripStation[];
  lineColor: string;
  lineName?: string;
  x?: number;
  className?: string;
  /** Prepared adjacent segment states (length = stations.length - 1). */
  segmentStates: readonly StripSegmentState[];
  /** Prepared per-station out-of-use flags. */
  stationOutOfUse: readonly boolean[];
  forceLabelIds?: readonly string[];
  /**
   * Shared fit scale for a group of strips (e.g. homepage week-ahead).
   * When set, every line uses the same pitch and type size, left-aligned.
   * When omitted, this strip scales itself to its container.
   */
  sharedFitScale?: number;
  labelPlacement?: StripLabelPlacement;
  trackStyle?: RouteTrackStyle;
};

/**
 * Fitted straight strip — left-aligned fixed pitch, no horizontal scroll.
 * Scales diagram unit `x` uniformly so station spacing and type stay consistent.
 */
export const StraightStripFitted = ({
  stations,
  lineColor,
  lineName,
  x,
  className,
  segmentStates,
  stationOutOfUse,
  forceLabelIds,
  sharedFitScale,
  labelPlacement = "above",
  trackStyle = "solid",
}: FittedProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;

    const update = () => setWidth(el.clientWidth);
    update();

    const observer = new ResizeObserver(() => update());
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const colWidthUnits = horizontalDiagramMetrics(labelPlacement).colWidthUnits;
  const colWidthPxApprox = DIAGRAM_BASELINE.horizontal * 0.85 * colWidthUnits;

  const selfScale =
    width > 0 && stations.length > 0
      ? Math.min(1, width / Math.max(colWidthPxApprox * stations.length, 1))
      : 1;
  const fitScale = sharedFitScale ?? selfScale;

  const unitStyle = (
    x != null
      ? { [DIAGRAM_X_VAR]: `${x * fitScale}px` }
      : {
          [DIAGRAM_X_VAR]: `calc(${DIAGRAM_BASELINE.horizontal}px * var(${DIAGRAM_SCALE_VAR}, 1) * ${fitScale})`,
        }
  ) as CSSProperties;

  const m = horizontalDiagramMetrics(labelPlacement);
  const maxConnections = stations.reduce(
    (n, s) =>
      Math.max(
        n,
        (s.connections ?? []).filter((c) => c.id !== "national-rail").length,
      ),
    0,
  );
  const connectionBand =
    maxConnections > 0
      ? `calc(${m.flagHeight} * ${maxConnections})`
      : undefined;
  const totalWidth = `calc(${m.colWidth} * ${stations.length})`;

  const labelIndexes =
    width > 0
      ? selectFittedLabelIndexes(
          stations,
          width,
          forceLabelIds,
          colWidthPxApprox * fitScale,
        )
      : new Set([
          0,
          stations.length - 1,
          ...(forceLabelIds
            ? stations.flatMap((s, i) =>
                forceLabelIds.includes(s.id) ? [i] : [],
              )
            : []),
        ]);

  return (
    <div
      ref={rootRef}
      className={cn("w-full min-w-0 overflow-x-hidden", className)}
      style={unitStyle}
    >
      {lineName ? (
        <div className="mb-3">
          <span
            className="inline-block px-2.5 py-1 font-semibold text-white"
            style={{ backgroundColor: lineColor, fontSize: m.titleSize }}
          >
            {lineName}
          </span>
        </div>
      ) : null}

      <div className="relative" style={{ width: totalWidth }}>
        <StraightRouteTrack
          stationCount={stations.length}
          segmentStates={segmentStates}
          lineColor={lineColor}
          lineTop={m.lineTop}
          lineWidth={m.lineWidth}
          colWidthUnits={m.colWidthUnits}
          trackStyle={trackStyle}
        />

        <ol className="relative m-0 flex list-none items-start p-0">
          {stations.map((station, index) => (
            <StraightStripStationColumn
              key={`${station.id}-${index}`}
              station={station}
              index={index}
              lineColor={lineColor}
              showLabel={labelIndexes.has(index)}
              connectionBand={connectionBand}
              colWidth={m.colWidth}
              outOfUse={stationOutOfUse[index] ?? false}
              labelPlacement={labelPlacement}
            />
          ))}
        </ol>
      </div>
    </div>
  );
};

"use client";

import { StationName } from "@/components/tfl/station-name";
import { OUT_OF_USE_LINE_COLOR } from "@/components/tfl/diagram/straight-strip-parts";
import {
  placeBranchStripLabels,
  verticalLabelOnLeft,
} from "@/lib/tfl/branch-strip-layout";
import {
  DIAGRAM_BASELINE,
  LINE_DIAGRAM,
  horizontalStationFontSize,
  scale,
  verticalStationFontSize,
} from "@/lib/tfl/line-diagram";
import type { LineSchematic } from "@/lib/tfl/line-schematic";
import {
  layoutLineSchematic,
  type SchematicLayoutPoint,
  type SchematicOrientation,
} from "@/lib/tfl/schematic-layout";
import {
  branchSegmentKey,
  type BranchStripLabelMap,
  type StripSegmentState,
} from "@/lib/tfl/strip-model";
import { cn } from "@/lib/utils";

/**
 * Atomic branched strip: SVG paths + markers, HTML StationName overlay.
 *
 * ## Visual regression checklist (run after every edit)
 * Open http://localhost:3999/primitives/branch-strip and confirm:
 * 1. **Mill Hill East** curves into Finchley with a Bezier — never a flat 90° stub
 *    (same `pos` as Finchley is forbidden; see `schematic-layout.test.ts`)
 * 2. **Camden → Mornington Crescent** is a smooth S-curve — never a staircase / elbow
 * 3. **No station labels overlap** each other; prefer labels clear of the track
 * 4. **Every tick/dash is ⊥ to the local track** — never parallel (esp. Mill Hill)
 *
 * Automated guards: `pnpm test` → `lib/tfl/schematic-layout.test.ts`
 */
export type BranchStripProps = {
  schematic: LineSchematic;
  lineColor: string;
  orientation?: SchematicOrientation;
  /**
   * Absolute diagram unit (= route line thickness).
   * Defaults to `DIAGRAM_BASELINE` for the orientation — same as straight strips.
   */
  x?: number;
  className?: string;
  /**
   * Editorial visual lines keyed by schematic node id.
   * Prepared by `LineStrip` / `prepareBranchStrip` — never looked up here.
   */
  nodeLabelLines?: BranchStripLabelMap;
  /**
   * Optional segment overrides keyed `"fromId→toId"`.
   * Lets closures paint without redesigning the schematic.
   */
  segmentStates?: Readonly<Record<string, StripSegmentState>>;
};

export const BranchStrip = ({
  schematic,
  lineColor,
  orientation: orientationProp,
  x: xProp,
  className,
  nodeLabelLines,
  segmentStates,
}: BranchStripProps) => {
  const orientation = orientationProp ?? schematic.orientation;
  const isHorizontal = orientation === "horizontal";
  const x = xProp ?? DIAGRAM_BASELINE[orientation];
  const strokeWidth = scale(x, LINE_DIAGRAM.lineThickness);
  const tickProtrude = scale(x, LINE_DIAGRAM.stationTick);
  const ringOuter = scale(x, LINE_DIAGRAM.interchange.outerDiameter / 2);
  const ringStroke = scale(x, LINE_DIAGRAM.interchange.stroke);
  // Clear interchange rings; keep text off the stroke where possible.
  const labelClearance = ringOuter + scale(x, 1.1);
  const nameFont = isHorizontal
    ? horizontalStationFontSize(x)
    : verticalStationFontSize(x);

  const mainPitch = scale(x, isHorizontal ? 12 : 14);
  // Wider vertical lanes so CX / Bank labels sit on opposite sides without clash.
  const lanePitch = scale(x, isHorizontal ? 10 : 20);

  const labelBand = Math.max(
    scale(x, LINE_DIAGRAM.layout.nameBelowLine) + nameFont * 1.15,
    nameFont * 2.2,
  );
  const labelBandTop = isHorizontal
    ? labelBand + labelClearance
    : nameFont * 2.4 + labelClearance;
  const labelBandBottom = isHorizontal ? labelBand + labelClearance : scale(x, 4);
  const verticalLabelWidth = Math.round(
    Math.min(scale(x, 16), lanePitch * 0.65),
  );
  const labelSideLeft = isHorizontal ? 0 : verticalLabelWidth + scale(x, 4);
  const labelSideRight = isHorizontal ? 0 : verticalLabelWidth + scale(x, 4);

  const layout = layoutLineSchematic(schematic, {
    orientation,
    x,
    mainPitch,
    lanePitch,
    padding: scale(x, isHorizontal ? 4 : 6),
  });

  // Narrower than station pitch so neighbours on the same corridor don’t collide.
  const labelMaxWidth = Math.max(scale(x, 7), layout.mainPitch * 0.7);
  const endPad = isHorizontal ? labelMaxWidth / 2 + scale(x, 1) : 0;
  const labelGap = ringOuter + scale(x, 2.5);

  const placements = placeBranchStripLabels(layout, {
    orientation,
    nameFont,
    labelMaxWidth,
    verticalLabelWidth,
    labelClearance,
    labelGap,
  });
  const placementById = new Map(placements.map((p) => [p.id, p]));

  const canvasWidth = layout.width + labelSideLeft + labelSideRight + endPad * 2;
  const canvasHeight = layout.height + labelBandTop + labelBandBottom;
  const svgOffsetX = labelSideLeft + endPad;
  const svgOffsetY = labelBandTop;

  return (
    <div
      className={cn("relative w-full min-w-0 overflow-auto", className)}
      role="region"
      aria-label={`${schematic.lineName} branch strip`}
      tabIndex={0}
    >
      <div
        className="relative"
        style={{ width: canvasWidth, height: canvasHeight }}
      >
        <svg
          width={canvasWidth}
          height={canvasHeight}
          className="absolute inset-0"
          aria-hidden
        >
          <g transform={`translate(${svgOffsetX} ${svgOffsetY})`}>
            {layout.edges.map((edge) => {
              const override =
                segmentStates?.[branchSegmentKey(edge.from, edge.to)] ??
                segmentStates?.[branchSegmentKey(edge.to, edge.from)];
              const state = override ?? edge.state;
              const stroke =
                state === "out-of-use" ? OUT_OF_USE_LINE_COLOR : lineColor;
              return (
                <path
                  key={`${edge.branchId ?? "edge"}:${edge.from}→${edge.to}`}
                  d={edge.path}
                  fill="none"
                  stroke={stroke}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              );
            })}

            {layout.points.map((point) => (
              <BranchStripMarker
                key={`m-${point.id}`}
                point={point}
                lineColor={lineColor}
                strokeWidth={strokeWidth}
                tickProtrude={tickProtrude}
                ringOuter={ringOuter}
                ringStroke={ringStroke}
                routeAlongMain={point.trackAxis === "x"}
              />
            ))}
          </g>
        </svg>

        {layout.points.map((point) => {
          const nodeX = point.x + svgOffsetX;
          const nodeY = point.y + svgOffsetY;
          const labelLines = nodeLabelLines?.[point.id];
          const placement = placementById.get(point.id);
          const labelStyle = {
            fontSize: nameFont,
            lineHeight: 1.15,
            textShadow:
              "0 0 3px var(--background), 0 0 3px var(--background), 0 0 6px var(--background)",
          } as const;

          if (isHorizontal) {
            const labelAbove = (placement?.side ?? "above") === "above";

            return (
              <div
                key={`label-${point.id}`}
                className="pointer-events-auto absolute z-10"
                style={{
                  left: nodeX,
                  top: labelAbove
                    ? nodeY - labelClearance
                    : nodeY + labelClearance,
                  width: labelMaxWidth,
                  transform: labelAbove
                    ? "translate(-50%, -100%)"
                    : "translate(-50%, 0)",
                }}
              >
                <StationName
                  name={point.name}
                  lines={labelLines}
                  layout="auto"
                  maxWidth={labelMaxWidth}
                  maxLines={2}
                  allowScaleDown={false}
                  align="center"
                  className="font-medium text-foreground"
                  style={labelStyle}
                />
              </div>
            );
          }

          if (placement?.side === "stub-above") {
            return (
              <div
                key={`label-${point.id}`}
                className="pointer-events-auto absolute z-10"
                style={{
                  left: nodeX,
                  top: nodeY - labelClearance,
                  width: verticalLabelWidth,
                  transform: "translate(-50%, -100%)",
                }}
              >
                <StationName
                  name={point.name}
                  lines={labelLines}
                  layout="auto"
                  maxWidth={verticalLabelWidth}
                  maxLines={2}
                  allowScaleDown={false}
                  allowAbbreviation={false}
                  align="center"
                  className="font-medium text-foreground"
                  style={labelStyle}
                />
              </div>
            );
          }

          const labelOnLeft =
            placement?.side === "left" ||
            (placement?.side !== "right" &&
              verticalLabelOnLeft(point, layout));

          return (
            <div
              key={`label-${point.id}`}
              className="pointer-events-auto absolute z-10"
              style={{
                left: labelOnLeft
                  ? nodeX - labelGap - verticalLabelWidth
                  : nodeX + labelGap,
                top: nodeY,
                width: verticalLabelWidth,
                transform: "translateY(-50%)",
              }}
            >
              <StationName
                name={point.name}
                lines={labelLines}
                layout="auto"
                maxWidth={verticalLabelWidth}
                maxLines={2}
                allowScaleDown={false}
                allowAbbreviation={false}
                align={labelOnLeft ? "right" : "left"}
                className="font-medium text-foreground"
                style={labelStyle}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
};

type BranchStripMarkerProps = {
  point: SchematicLayoutPoint;
  lineColor: string;
  strokeWidth: number;
  tickProtrude: number;
  ringOuter: number;
  ringStroke: number;
  /** True when local track runs along the main (horizontal) axis. */
  routeAlongMain: boolean;
};

/**
 * Markers match StraightStrip / DiagramStationMarker:
 * - interchange → white ring (Ø 3x)
 * - terminus → filled end bar (perpendicular to local track)
 * - stop → cross-tick or tick-right
 */
const BranchStripMarker = ({
  point,
  lineColor,
  strokeWidth,
  tickProtrude,
  ringOuter,
  ringStroke,
  routeAlongMain,
}: BranchStripMarkerProps) => {
  if (point.kind === "interchange") {
    return (
      <circle
        cx={point.x}
        cy={point.y}
        r={ringOuter}
        fill="#fff"
        stroke="#000"
        strokeWidth={ringStroke}
      />
    );
  }

  const halfLen = strokeWidth / 2 + tickProtrude;

  if (point.kind === "terminus") {
    const half = strokeWidth / 2 + tickProtrude * 3.5;
    if (routeAlongMain) {
      return (
        <rect
          x={point.x - strokeWidth / 2}
          y={point.y - half}
          width={strokeWidth}
          height={half * 2}
          fill={lineColor}
        />
      );
    }
    return (
      <rect
        x={point.x - half}
        y={point.y - strokeWidth / 2}
        width={half * 2}
        height={strokeWidth}
        fill={lineColor}
      />
    );
  }

  if (routeAlongMain) {
    return (
      <rect
        x={point.x - strokeWidth / 2}
        y={point.y - halfLen}
        width={strokeWidth}
        height={strokeWidth + tickProtrude * 2}
        fill={lineColor}
      />
    );
  }

  return (
    <rect
      x={point.x - strokeWidth / 2}
      y={point.y - strokeWidth / 2}
      width={strokeWidth + tickProtrude}
      height={strokeWidth}
      fill={lineColor}
    />
  );
};

"use client";

import { BranchStrip } from "@/components/tfl/diagram/branch-strip";
import { StraightStrip } from "@/components/tfl/diagram/straight-strip";
import { LineRouteDiagram } from "@/components/tfl/diagram/line-route-diagram";
import {
  sliceLineSpineStations,
  type LineSpine,
} from "@/lib/tfl/line-spine";
import type { DiagramSegment, DiagramStation } from "@/lib/tfl/diagram-station";
import type { LineSchematic } from "@/lib/tfl/line-schematic";
import {
  resolveDiagramLineColor,
  resolveRouteTrackStyle,
  type RouteTrackStyle,
} from "@/lib/tfl/route-track";
import {
  prepareBranchStrip,
  prepareStraightStrip,
  type StripLabelPlacement,
  type StripSegmentState,
} from "@/lib/tfl/strip-model";
import { cn } from "@/lib/utils";

export type LineStripOrientation = "horizontal" | "vertical";

export type LineStripProps = {
  lineId: string;
  /** Preloaded stations (week-ahead / demos). When omitted, pass via `spine`. */
  stations?: readonly DiagramStation[];
  lineName?: string;
  lineColor?: string;
  /** Full spine payload — alternative to stations + meta. */
  spine?: Pick<LineSpine, "stations" | "lineName" | "lineColor" | "routeError">;
  /**
   * When set, renders `BranchStrip` instead of a linear strip.
   * Orientation defaults to the schematic’s authored hint.
   */
  schematic?: LineSchematic;
  orientation?: LineStripOrientation;
  segments?: readonly DiagramSegment[];
  /** Stations whose markers use the out-of-use colour. */
  stationOutOfUseIds?: readonly string[];
  /** Branch edge overrides keyed `"fromId→toId"`. */
  branchSegmentStates?: Readonly<Record<string, StripSegmentState>>;
  fit?: boolean;
  forceLabelIds?: readonly string[];
  sharedFitScale?: number;
  labelPlacement?: StripLabelPlacement;
  /** Absolute diagram unit (horizontal). */
  x?: number;
  /** Inclusive partial spine by station id. */
  fromStationId?: string;
  toStationId?: string;
  className?: string;
  /** Scroll region wrapper for horizontal (default true). */
  scroll?: boolean;
  /**
   * Apply editorial strip label recipes (default true).
   * Set false when stations already carry `labelLines`.
   */
  applyLabelRecipes?: boolean;
  /**
   * Override route paint. Default resolves from `lineId`
   * (solid / Overground·Elizabeth parallel / cable-car triple).
   */
  trackStyle?: RouteTrackStyle;
};

/**
 * Molecular strip: TfL-aware compose layer.
 * Resolves colour, spine slicing, adjacency/closure presentation, and
 * editorial label breaks, then renders `StraightStrip` or `BranchStrip`.
 * Fetching stays in Server Component / data-loader parents.
 */
export const LineStrip = ({
  lineId,
  stations: stationsProp,
  lineName: lineNameProp,
  lineColor: lineColorProp,
  spine,
  schematic,
  orientation: orientationProp,
  segments,
  stationOutOfUseIds,
  branchSegmentStates,
  fit = false,
  forceLabelIds,
  sharedFitScale,
  x,
  fromStationId,
  toStationId,
  className,
  scroll = true,
  labelPlacement = "above",
  applyLabelRecipes = true,
  trackStyle: trackStyleProp,
}: LineStripProps) => {
  const color =
    lineColorProp ?? spine?.lineColor ?? resolveDiagramLineColor(lineId);
  const name = lineNameProp ?? spine?.lineName ?? lineId;
  const trackStyle = trackStyleProp ?? resolveRouteTrackStyle(lineId);
  const orientation: LineStripOrientation =
    orientationProp ?? schematic?.orientation ?? "horizontal";

  if (schematic) {
    const prepared = prepareBranchStrip(schematic, {
      segmentStates: branchSegmentStates,
      applyLabelRecipes,
    });
    return (
      <BranchStrip
        schematic={prepared.schematic}
        lineColor={color}
        orientation={orientation}
        x={x}
        className={className}
        nodeLabelLines={prepared.nodeLabelLines}
        segmentStates={prepared.segmentStates}
      />
    );
  }

  const rawStations = stationsProp ?? spine?.stations ?? [];
  const stations =
    fromStationId && toStationId
      ? sliceLineSpineStations(rawStations, fromStationId, toStationId)
      : [...rawStations];

  if (stations.length === 0) {
    return (
      <p className={cn("text-sm text-muted-foreground", className)}>
        {spine?.routeError ?? "No stations to display."}
      </p>
    );
  }

  if (orientation === "vertical") {
    return (
      <LineRouteDiagram
        stations={stations}
        lineColor={color}
        lineName={name}
        x={x}
        className={className}
      />
    );
  }

  const prepared = prepareStraightStrip(stations, {
    segments,
    stationOutOfUseIds,
    applyLabelRecipes,
  });

  const diagram = (
    <StraightStrip
      stations={prepared.stations}
      lineColor={color}
      lineName={name}
      segmentStates={prepared.segmentStates}
      stationOutOfUse={prepared.stationOutOfUse}
      fit={fit}
      forceLabelIds={forceLabelIds}
      sharedFitScale={sharedFitScale}
      labelPlacement={labelPlacement}
      trackStyle={trackStyle}
      x={x}
      className={scroll ? undefined : className}
    />
  );

  if (!scroll || fit) {
    return <div className={className}>{diagram}</div>;
  }

  return (
    <div
      className={cn(
        "overflow-x-auto overscroll-x-contain pb-2 [-webkit-overflow-scrolling:touch]",
        className,
      )}
      tabIndex={0}
      role="region"
      aria-label={`${name} line strip`}
    >
      {diagram}
    </div>
  );
};

"use client";

import { cn } from "@/lib/utils";
import {
  diagramUnitStyle,
  verticalDiagramMetrics,
} from "@/lib/tfl/line-diagram";
import { type DiagramStation } from "@/lib/tfl/diagram-station";
import {
  DiagramConnectionFlags,
  DiagramStationMarker,
  resolveMapMarkerKind,
  VerticalRouteLine,
} from "@/components/tfl/diagram/diagram-markers";
import { StationName } from "@/components/tfl/station-name";
import { NationalRailPictogram } from "@/components/tfl/national-rail-pictogram";

export type LineRouteDiagramProps = {
  stations: DiagramStation[];
  /** Hex route colour (use getLineColor / getLineInlineStyles in callers). */
  lineColor: string;
  lineName?: string;
  directionLabel?: string;
  /**
   * Absolute route line thickness in px.
   * When omitted, uses `DIAGRAM_BASELINE.vertical` × `--tfl-diagram-scale`.
   */
  x?: number;
  className?: string;
};

/**
 * Vertical full-line map: continuous route with right-side ticks, terminal
 * crossbars, interchange rings, and §11-scale station names.
 */
export const LineRouteDiagram = ({
  stations,
  lineColor,
  lineName,
  directionLabel,
  x,
  className,
}: LineRouteDiagramProps) => {
  if (stations.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">No stations to display.</p>
    );
  }

  const m = verticalDiagramMetrics();
  const lastIndex = stations.length - 1;

  return (
    <div
      className={cn("w-full", className)}
      style={diagramUnitStyle("vertical", x)}
    >
      {(lineName || directionLabel) && (
        <div className="mb-4 flex flex-wrap items-baseline gap-2">
          {lineName ? (
            <h2
              className="font-semibold"
              style={{ color: lineColor, fontSize: m.titleSize }}
            >
              {lineName}
            </h2>
          ) : null}
          {directionLabel ? (
            <span
              className="text-muted-foreground"
              style={{ fontSize: m.flagFont }}
            >
              {directionLabel}
            </span>
          ) : null}
        </div>
      )}

      <ol className="relative m-0 list-none p-0">
        <VerticalRouteLine
          lineColor={lineColor}
          markerCol={m.markerCol}
          rowGap={m.rowGap}
        />

        {stations.map((station, index) => {
          const kind = resolveMapMarkerKind({
            interchange: station.interchange,
            isEndpoint: index === 0 || index === lastIndex,
          });
          const connections = station.connections;

          return (
            <li
              key={`${station.id}-${index}`}
              className="relative flex items-center"
              style={{
                minHeight: m.rowGap,
                columnGap: m.nameGap,
              }}
            >
              <DiagramStationMarker
                kind={kind}
                lineColor={lineColor}
                columnWidth={m.markerCol}
                slotHeight={m.markerSlot}
              />

              <div className="flex min-w-0 flex-1 items-center gap-2">
                <div className="relative inline-flex min-w-0 max-w-full items-center">
                  <StationName
                    name={station.name}
                    layout="auto"
                    maxLines={2}
                    align="left"
                    className="min-w-0 font-medium text-foreground"
                    style={{ fontSize: m.nameSize }}
                  />
                  {station.nationalRail ? (
                    <span className="ml-1 inline-flex shrink-0 items-center self-end pb-0.5">
                      <NationalRailPictogram height="0.75em" />
                      <span className="sr-only">National Rail</span>
                    </span>
                  ) : null}
                </div>
                {connections &&
                connections.filter((c) => c.id !== "national-rail").length >
                  0 ? (
                  <DiagramConnectionFlags
                    stationId={station.id}
                    connections={connections.filter(
                      (c) => c.id !== "national-rail",
                    )}
                  />
                ) : null}
              </div>
            </li>
          );
        })}
      </ol>
    </div>
  );
};

"use client";

import { useState } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  diagramUnitStyle,
  verticalDiagramMetrics,
} from "@/lib/tfl/line-diagram";
import { type DiagramStation } from "@/lib/tfl/diagram-station";
import { Button } from "@/components/ui/button";
import {
  DiagramConnectionFlags,
  DiagramStationMarker,
  resolveJourneyMarkerKind,
  VerticalRouteLine,
} from "@/components/tfl/diagram/diagram-markers";
import { StationName } from "@/components/tfl/station-name";
import { NationalRailPictogram } from "@/components/tfl/national-rail-pictogram";

export type JourneyDiagramProps = {
  from: DiagramStation;
  to: DiagramStation;
  /** Stops between from and to (exclusive). */
  intermediates?: DiagramStation[];
  lineColor: string;
  lineName?: string;
  defaultExpanded?: boolean;
  /**
   * Absolute route line thickness in px.
   * When omitted, uses `DIAGRAM_BASELINE.vertical` × `--tfl-diagram-scale`.
   */
  x?: number;
  className?: string;
};

const StationRow = ({
  station,
  lineColor,
}: {
  station: DiagramStation;
  lineColor: string;
}) => {
  const m = verticalDiagramMetrics();
  const kind = resolveJourneyMarkerKind();
  const connections = (station.connections ?? []).filter(
    (c) => c.id !== "national-rail",
  );

  return (
    <div
      className="relative flex items-center"
      style={{
        columnGap: m.nameGap,
        minHeight: m.rowGap,
      }}
    >
      <DiagramStationMarker
        kind={kind}
        lineColor={lineColor}
        columnWidth={m.markerCol}
        slotHeight={m.markerSlot}
      />
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <div className="relative inline-flex min-w-0 max-w-full items-center">
          <StationName
            name={station.name}
            layout="auto"
            maxLines={2}
            align="left"
            className="min-w-0 font-medium text-foreground"
            style={{ fontSize: m.nameSize }}
          />
          {station.nationalRail ? (
            <span className="ml-1 inline-flex shrink-0 items-center self-end pb-0.5">
              <NationalRailPictogram height="0.75em" />
              <span className="sr-only">National Rail</span>
            </span>
          ) : null}
        </div>
        {connections.length > 0 ? (
          <DiagramConnectionFlags
            stationId={station.id}
            connections={connections}
          />
        ) : null}
      </div>
    </div>
  );
};

/**
 * A→B journey on one line: endpoints always visible; intermediate stops
 * collapse behind an expand control. Journey markers are always circles.
 */
export const JourneyDiagram = ({
  from,
  to,
  intermediates = [],
  lineColor,
  lineName,
  defaultExpanded = false,
  x,
  className,
}: JourneyDiagramProps) => {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const m = verticalDiagramMetrics();
  const stopCount = intermediates.length;

  const handleToggle = () => setExpanded((v) => !v);

  return (
    <div
      className={cn("w-full", className)}
      style={diagramUnitStyle("vertical", x)}
    >
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
        {lineName ? (
          <p
            className="font-semibold"
            style={{ color: lineColor, fontSize: m.titleSize }}
          >
            {lineName}
          </p>
        ) : (
          <span />
        )}
        {stopCount > 0 ? (
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleToggle}
            aria-expanded={expanded}
            className="gap-1.5"
          >
            {expanded ? (
              <>
                Hide stops
                <ChevronUp className="size-3.5" aria-hidden />
              </>
            ) : (
              <>
                {stopCount} stop{stopCount === 1 ? "" : "s"}
                <ChevronDown className="size-3.5" aria-hidden />
              </>
            )}
          </Button>
        ) : null}
      </div>

      <div className="relative">
        <VerticalRouteLine
          lineColor={lineColor}
          markerCol={m.markerCol}
          rowGap={m.rowGap}
        />

        <div className="relative flex flex-col" style={{ gap: m.stopGap }}>
          <StationRow station={from} lineColor={lineColor} />

          {stopCount > 0 && !expanded ? (
            <button
              type="button"
              onClick={handleToggle}
              className="relative flex w-full items-center rounded-md text-left transition-colors hover:bg-muted/60"
              style={{ columnGap: m.nameGap, minHeight: m.rowGap }}
              aria-label={`Show ${stopCount} intermediate stops`}
            >
              <div
                className="relative z-10 flex shrink-0 items-center justify-center"
                style={{ width: m.markerCol, height: m.markerSlot }}
              >
                <span
                  className="block rounded-full bg-background ring-2 ring-muted-foreground/40"
                  style={{ width: m.lineWidth, height: m.lineWidth }}
                  aria-hidden
                />
              </div>
              <span
                className="text-muted-foreground"
                style={{ fontSize: `calc(${m.nameSize} * 0.75)` }}
              >
                {stopCount} intermediate stop{stopCount === 1 ? "" : "s"}
              </span>
            </button>
          ) : null}

          {expanded
            ? intermediates.map((station) => (
                <StationRow
                  key={station.id}
                  station={station}
                  lineColor={lineColor}
                />
              ))
            : null}

          <StationRow station={to} lineColor={lineColor} />
        </div>
      </div>
    </div>
  );
};

import type { CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { ux, verticalDiagramMetrics } from "@/lib/tfl/line-diagram";

export type DiagramMarkerKind = "tick-right" | "tick-both" | "ring";

export type DiagramStationMarkerProps = {
  kind: DiagramMarkerKind;
  lineColor: string;
  /** Marker column width (CSS length). Defaults to vertical metrics. */
  columnWidth?: string;
  /** Row / column height for the marker slot (CSS length). */
  slotHeight?: string;
  className?: string;
};

/**
 * Shared stop marker for vertical / journey diagrams.
 * - tick-right: mid-route dash on the label side of the route only
 * - tick-both: terminal crossbar (both sides)
 * - ring: interchange / journey stop (white fill, black outline)
 */
export const DiagramStationMarker = ({
  kind,
  lineColor,
  columnWidth,
  slotHeight,
  className,
}: DiagramStationMarkerProps) => {
  const m = verticalDiagramMetrics();
  const width = columnWidth ?? m.markerCol;
  const height = slotHeight ?? m.markerSlot;

  return (
    <div
      className={cn(
        "relative z-10 flex shrink-0 items-center justify-center",
        className,
      )}
      style={{ width, height }}
    >
      {kind === "ring" ? (
        <span
          className="box-border block rounded-full bg-white"
          style={{
            width: m.ringOuter,
            height: m.ringOuter,
            borderWidth: m.ringStroke,
            borderStyle: "solid",
            borderColor: "#000",
          }}
          aria-hidden
        />
      ) : null}

      {kind === "tick-both" ? (
        <span
          className="block"
          style={{
            width: m.tickBothWidth,
            height: m.tickHeight,
            backgroundColor: lineColor,
          }}
          aria-hidden
        />
      ) : null}

      {kind === "tick-right" ? (
        <span
          className="absolute top-1/2 block -translate-y-1/2"
          style={{
            /* Align tick left edge with route-line left edge (column centre − ½x). */
            left: `calc(50% - (${m.lineWidth} / 2))`,
            width: m.tickRightWidth,
            height: m.tickHeight,
            backgroundColor: lineColor,
          }}
          aria-hidden
        />
      ) : null}
    </div>
  );
};

export type DiagramConnectionFlagsProps = {
  stationId: string;
  connections: {
    id: string;
    name: string;
    color?: string;
    darkText?: boolean;
  }[];
};

/** §9-style stacked flag chips beside a vertical station name. */
export const DiagramConnectionFlags = ({
  stationId,
  connections,
}: DiagramConnectionFlagsProps) => {
  const m = verticalDiagramMetrics();
  if (connections.length === 0) return null;

  return (
    <div
      className="inline-flex shrink-0 flex-col"
      aria-label={`Connections: ${connections.map((c) => c.name).join(", ")}`}
    >
      {connections.map((c) => (
        <span
          key={`${stationId}-${c.id}`}
          className="flex w-full items-center justify-center px-1.5 leading-none font-medium whitespace-nowrap"
          style={{
            backgroundColor: c.color ?? "#64748b",
            color: c.darkText ? "#0019A8" : "#fff",
            height: m.flagHeight,
            minWidth: m.flagMinWidth,
            fontSize: m.flagFont,
          }}
        >
          {c.name}
        </span>
      ))}
    </div>
  );
};

/**
 * Continuous vertical route line centred on the marker column.
 * Top/bottom inset = half the uniform row pitch so the line starts and ends
 * on the first/last marker centres, with no stub segment.
 */
export const VerticalRouteLine = ({
  lineColor,
  markerCol,
  rowGap,
  className,
}: {
  lineColor: string;
  markerCol: string;
  rowGap: string;
  className?: string;
}) => (
  <div
    aria-hidden
    className={cn(
      "pointer-events-none absolute left-[calc(var(--marker)/2)] -translate-x-1/2",
      className,
    )}
    style={
      {
        "--marker": markerCol,
        top: `calc(${rowGap} / 2)`,
        bottom: `calc(${rowGap} / 2)`,
        width: ux(1),
        backgroundColor: lineColor,
      } as CSSProperties
    }
  />
);

/**
 * Full-line / map markers: interchange → ring; terminal → both-side tick;
 * mid-route → right-side tick only.
 */
export const resolveMapMarkerKind = ({
  interchange,
  isEndpoint,
}: {
  interchange?: boolean;
  isEndpoint?: boolean;
}): DiagramMarkerKind => {
  if (interchange) return "ring";
  if (isEndpoint) return "tick-both";
  return "tick-right";
};

/** Journey A→B markers are always circles. */
export const resolveJourneyMarkerKind = (): DiagramMarkerKind => "ring";

import { cn } from "@/lib/utils";
import {
  bend90Path,
  continuationArrowPoints,
  interchangeOuterRadius,
  interchangeStroke,
  LINE_DIAGRAM,
  scale,
  stationTickRect,
} from "@/lib/tfl/line-diagram";

type ShapeProps = {
  /** Route line thickness in CSS pixels (= unit x). Default 12. */
  x?: number;
  className?: string;
  /** Line / fill colour for the route. */
  color?: string;
};

const DEFAULT_X = 12;

/** Solid route segment with a 0.66x station tick. */
export const DiagramStationTick = ({
  x = DEFAULT_X,
  className,
  color = "#DC241F",
}: ShapeProps) => {
  const w = scale(x, 6);
  const h = scale(x, 3);
  const cy = h / 2;
  const tick = stationTickRect(w * 0.45, cy, x);
  return (
    <svg
      viewBox={`0 0 ${w} ${h}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="Station tick"
    >
      <rect y={cy - x / 2} width={w} height={x} fill={color} />
      <rect
        x={tick.x}
        y={cy - x / 2 - tick.height}
        width={tick.width}
        height={tick.height}
        fill={color}
      />
    </svg>
  );
};

/** Parallel (non-Underground) double line as used on the Tube map. */
export const DiagramParallelLines = ({
  x = DEFAULT_X,
  className,
  color = "#00AFAD",
}: ShapeProps) => {
  const stroke = scale(x, LINE_DIAGRAM.parallel.stroke);
  const gap = scale(x, LINE_DIAGRAM.parallel.gap);
  const total = stroke * 2 + gap;
  const w = scale(x, 8);
  return (
    <svg
      viewBox={`0 0 ${w} ${total}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="Parallel route lines"
    >
      <rect y={0} width={w} height={stroke} fill={color} />
      <rect y={stroke + gap} width={w} height={stroke} fill={color} />
    </svg>
  );
};

/** 90° bend with innermost radius R3x. */
export const DiagramBend90 = ({
  x = DEFAULT_X,
  className,
  color = "#F589A6",
}: ShapeProps) => {
  const pad = scale(x, 1);
  const r = scale(x, LINE_DIAGRAM.innerCurveRadius + 0.5);
  const size = r + pad * 2 + x;
  const startX = pad;
  const startY = pad + x / 2;
  const d = bend90Path(startX, startY, x, "down-right");
  return (
    <svg
      viewBox={`0 0 ${size} ${size}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="90 degree bend radius 3x"
    >
      <path
        d={d}
        fill="none"
        stroke={color}
        strokeWidth={x}
        strokeLinecap="butt"
        strokeLinejoin="round"
      />
    </svg>
  );
};

/** Continuation arrow head (§7). */
export const DiagramArrowHead = ({
  x = DEFAULT_X,
  className,
  color = "#B26300",
}: ShapeProps) => {
  const tipX = scale(x, 5);
  const cy = scale(x, 2);
  const w = tipX + scale(x, 0.5);
  const h = scale(x, 4);
  const points = continuationArrowPoints(tipX, cy, x, 1);
  return (
    <svg
      viewBox={`0 0 ${w} ${h}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="Continuation arrow head"
    >
      <rect
        x={0}
        y={cy - x / 2}
        width={Math.max(0, tipX - scale(x, 2))}
        height={x}
        fill={color}
      />
      <polygon points={points} fill={color} />
    </svg>
  );
};

/** Single interchange ring on a route line (§8). */
export const DiagramInterchangeCircle = ({
  x = DEFAULT_X,
  className,
  color = "#DC241F",
}: ShapeProps) => {
  const outer = interchangeOuterRadius(x);
  const stroke = interchangeStroke(x);
  const size = outer * 2 + scale(x, 2);
  const cx = size / 2;
  const cy = size / 2;
  return (
    <svg
      viewBox={`0 0 ${size} ${size}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="Interchange circle"
    >
      <rect y={cy - x / 2} width={size} height={x} fill={color} />
      <circle
        cx={cx}
        cy={cy}
        r={outer - stroke / 2}
        fill="#fff"
        stroke="#000"
        strokeWidth={stroke}
      />
    </svg>
  );
};

/** Dumbbell / bridged double interchange (§8). */
export const DiagramInterchangeDumbbell = ({
  x = DEFAULT_X,
  className,
}: ShapeProps) => {
  const outer = interchangeOuterRadius(x);
  const stroke = interchangeStroke(x);
  const neckW = scale(x, LINE_DIAGRAM.interchange.neckWidth);
  const gap = scale(x, LINE_DIAGRAM.interchange.bridgeWhite);
  const sizeW = outer * 2 + scale(x, 1);
  const cy1 = outer + scale(x, 0.25);
  // Centre distance = outer + inner = 1.5x + 1x = 2.5x
  const cy2 = cy1 + scale(x, 2.5);
  const cx = sizeW / 2;
  const h = cy2 + outer + scale(x, 0.25);
  return (
    <svg
      viewBox={`0 0 ${sizeW} ${h}`}
      className={cn("overflow-visible", className)}
      role="img"
      aria-label="Dumbbell interchange"
    >
      <circle
        cx={cx}
        cy={cy1}
        r={outer - stroke / 2}
        fill="#fff"
        stroke="#000"
        strokeWidth={stroke}
      />
      <circle
        cx={cx}
        cy={cy2}
        r={outer - stroke / 2}
        fill="#fff"
        stroke="#000"
        strokeWidth={stroke}
      />
      <rect
        x={cx - neckW / 2}
        y={cy1}
        width={neckW}
        height={cy2 - cy1}
        fill="#000"
      />
      <rect
        x={cx - gap / 2}
        y={cy1 - 1}
        width={gap}
        height={cy2 - cy1 + 2}
        fill="#fff"
      />
    </svg>
  );
};

/**
 * TfL Line diagram standard — Issue 4 (January 2025) geometry.
 * Unit `x` = station-name x-height = solid route-line thickness.
 * These helpers encode published ratios for map/diagram drawing.
 * They do not grant a licence to reproduce TfL maps.
 */

import type { CSSProperties } from "react";

/** Base unit: route line thickness (= station name x-height). */
export type DiagramUnit = number;

export const LINE_DIAGRAM_SOURCE = {
  title: "Line diagram standard",
  issue: 4,
  date: "January 2025",
  referencePdf: "reference/brand/tfl-line-diagram-standard.pdf",
  assetsRoot: "/brand/line-diagram",
  manifest: "/brand/line-diagram/manifest.json",
} as const;

/**
 * Inherited CSS scale for all strip components on a page.
 * Set once on a parent (e.g. the `/components/line-strip` region) with Tailwind
 * breakpoints; do not theme tick/ring/type ratios independently.
 *
 * @example
 * ```tsx
 * <div className="[--tfl-diagram-scale:0.7] sm:[--tfl-diagram-scale:0.85] lg:[--tfl-diagram-scale:1]">
 *   <LineStrip … />
 *   <JourneyDiagram … />
 * </div>
 * ```
 */
export const DIAGRAM_SCALE_VAR = "--tfl-diagram-scale";

/** Resolved route-line thickness used inside each diagram root. */
export const DIAGRAM_X_VAR = "--tfl-diagram-x";

/**
 * Orientation baselines (px at scale 1).
 * Horizontal `10` matches the Victoria strip reference.
 * Vertical `4` keeps §11 proportions (names taller than rings) while landing
 * station type near body/`text-base` size (~17px) on a laptop screen.
 */
export const DIAGRAM_BASELINE = {
  horizontal: 10,
  vertical: 4,
} as const;

export type DiagramOrientation = keyof typeof DIAGRAM_BASELINE;

/**
 * Suggested page-level responsive scale values (unitless multipliers).
 * Apply via Tailwind arbitrary properties on a shared ancestor.
 */
export const DIAGRAM_SCALE = {
  mobile: 0.7,
  tablet: 0.85,
  desktop: 1,
} as const;

/** Tailwind class string that sets `--tfl-diagram-scale` at shared breakpoints. */
export const DIAGRAM_SCALE_CLASS = `[${DIAGRAM_SCALE_VAR}:${DIAGRAM_SCALE.mobile}] sm:[${DIAGRAM_SCALE_VAR}:${DIAGRAM_SCALE.tablet}] lg:[${DIAGRAM_SCALE_VAR}:${DIAGRAM_SCALE.desktop}]`;

/**
 * Sets `--tfl-diagram-x` on a diagram root.
 * Pass `x` to lock an absolute thickness; otherwise baseline × inherited scale.
 */
export const diagramUnitStyle = (
  orientation: DiagramOrientation,
  x?: number,
): CSSProperties =>
  ({
    [DIAGRAM_X_VAR]:
      x != null
        ? `${x}px`
        : `calc(${DIAGRAM_BASELINE[orientation]}px * var(${DIAGRAM_SCALE_VAR}, 1))`,
  }) as CSSProperties;

/** CSS length = `units` × `--tfl-diagram-x`. */
export const ux = (units: number): string =>
  `calc(var(${DIAGRAM_X_VAR}) * ${units})`;

/** Core proportions (§5–§8). All values are multiples of `x`. */
export const LINE_DIAGRAM = {
  /** Solid route line thickness. */
  lineThickness: 1,
  /** Station tick — square on the line (§5). */
  stationTick: 0.66,
  /** Non-Underground parallel lines on Tube map (§5). */
  parallel: {
    stroke: 0.33,
    gap: 0.33,
    /** Total stack ≈ x */
    total: 0.99,
  },
  /** Engineering works / out of use (§5.1). Solid uses theme `--muted` (~zinc-100). */
  outOfUse: {
    m: 0.33,
    /** Dash segment length in units of m (legacy dashed style). */
    dashM: 0.5,
    colorOpacity: 0.3,
  },
  /** Direction changes (§6). */
  angles: [45, 90] as const,
  /** Innermost adjacent curve radius (§6). */
  innerCurveRadius: 3,
  /** Continuation arrow (§7). Total height = 4x. */
  arrow: {
    wing: 1.5,
    stem: 1,
    /** Perpendicular arm thickness */
    armThickness: 1,
    tipHalfAngleDeg: 45,
  },
  /** Interchange circle (§8). Outer diameter = 3x. */
  interchange: {
    stroke: 0.5,
    innerDiameter: 2,
    outerDiameter: 3,
    /** White bridge strip between joined circles */
    bridgeWhite: 0.5,
    /** Black neck walls on dumbbell */
    bridgeBorder: 0.5,
    /** Total neck width = 1.5x */
    neckWidth: 1.5,
  },
  /** Horizontal diagram layout (§10). */
  layout: {
    /** Gap from line underside to station name top when name is below */
    nameBelowLine: 1.66,
    /** Minimum gap between adjacent flag boxes (in CH) — use with cap height */
    flagGapCh: 1,
    /** Single-line flag box height parts in CH: 0.25 + 0.5 + 0.25 */
    flagPaddingCh: { top: 0.25, text: 0.5, bottom: 0.25 },
    /** Overground flag height = 1.5 × CH (§9.3) */
    overgroundFlagHeightCh: 1.5,
  },
  /** Vertical platform diagrams (§11). Unit `n` = route line width. */
  vertical: {
    /** Station name capital-letter height = 3 × route line width. */
    nameCapHeight: 3,
    flagDepth: 1.5,
    curveRadiusMain: 3,
    curveRadiusBranch: 4,
    tick: 0.66,
  },
} as const;

export const scale = (x: DiagramUnit, units: number): number => x * units;

/**
 * Hammersmith One / Johnston-like fonts: capital height ≈ 70% of CSS font-size.
 * Used to convert §11 cap-height (3x) into a CSS `font-size`.
 */
export const DIAGRAM_CAP_HEIGHT_RATIO = 0.7;

/** §11 name size as a multiple of `x` (cap height 3x → CSS font-size). */
export const VERTICAL_NAME_SIZE_UNITS =
  LINE_DIAGRAM.vertical.nameCapHeight / DIAGRAM_CAP_HEIGHT_RATIO;

/** Horizontal station name: x-height ≈ line thickness → CSS font-size ≈ 2x. */
export const HORIZONTAL_NAME_SIZE_UNITS = 2;

/** §11: CSS font-size so station-name capitals match interchange outer Ø (3x). */
export const verticalStationFontSize = (x: DiagramUnit): number =>
  scale(x, VERTICAL_NAME_SIZE_UNITS);

/** Flag chip font roughly half the station name size. */
export const verticalFlagFontSize = (x: DiagramUnit): number =>
  Math.max(10, verticalStationFontSize(x) * 0.45);

/**
 * §5 / §10: CSS font-size so station-name x-height ≈ route line thickness `x`
 * (Johnston-like x-height ≈ half an em).
 */
export const horizontalStationFontSize = (x: DiagramUnit): number =>
  scale(x, HORIZONTAL_NAME_SIZE_UNITS);

/** Capital height from a CSS font-size (Johnston-like). */
export const stationCapHeight = (fontSize: number): number =>
  fontSize * DIAGRAM_CAP_HEIGHT_RATIO;

/**
 * §9 single-line flag box height = 1 CH
 * (0.25 + 0.5 + 0.25 padding/text parts).
 */
export const flagBoxHeight = (capHeight: number): number => {
  const { top, text, bottom } = LINE_DIAGRAM.layout.flagPaddingCh;
  return capHeight * (top + text + bottom);
};

/** §9: font-size so capitals fill the flag text band (0.5 CH). */
export const flagBoxFontSize = (capHeight: number): number =>
  (capHeight * LINE_DIAGRAM.layout.flagPaddingCh.text) /
  DIAGRAM_CAP_HEIGHT_RATIO;

/** §10: gap from route line underside to content below (names / flags). */
export const belowLineClearance = (x: DiagramUnit): number =>
  scale(x, LINE_DIAGRAM.layout.nameBelowLine);

/**
 * Shared CSS lengths for vertical / journey diagrams (multiples of `--tfl-diagram-x`).
 * Keeps JourneyDiagram and LineRouteDiagram from drifting apart.
 *
 * Vertical UI names use §11 sizing (cap height ≈ ring Ø = 3×) so labels read
 * taller than interchange rings. Mid-route ticks protrude right only;
 * terminals use a full crossbar.
 */
export const verticalDiagramMetrics = () => {
  const tickProtrude = LINE_DIAGRAM.vertical.tick;
  /** Full terminal tick (both sides of the route). */
  const tickBothWidth = 1 + tickProtrude * 2;
  /** Mid-route tick: covers the line and extends right only. */
  const tickRightWidth = 1 + tickProtrude;
  const ringOuter = LINE_DIAGRAM.interchange.outerDiameter;
  const ringStroke = LINE_DIAGRAM.interchange.stroke;
  /** §11: capitals ≈ ring Ø → CSS font-size taller than the ring. */
  const nameSize = VERTICAL_NAME_SIZE_UNITS;
  const capHeight = nameSize * DIAGRAM_CAP_HEIGHT_RATIO;
  const { top, text, bottom } = LINE_DIAGRAM.layout.flagPaddingCh;
  const flagHeight = capHeight * (top + text + bottom);
  const flagFont = (capHeight * text) / DIAGRAM_CAP_HEIGHT_RATIO;
  const flagMinWidth = Math.max(8, capHeight * 4);
  const markerCol = Math.max(ringOuter, tickBothWidth);
  const nameGap = 1.5;
  /** Extra pitch so names taller than rings still breathe between stops. */
  const rowGap = Math.max(ringOuter, nameSize) + 2.5;
  const stopGap = 2;

  return {
    tickProtrude: ux(tickProtrude),
    tickBothWidth: ux(tickBothWidth),
    tickRightWidth: ux(tickRightWidth),
    tickHeight: ux(1),
    ringOuter: ux(ringOuter),
    ringStroke: ux(ringStroke),
    markerSlot: ux(ringOuter),
    nameSize: ux(nameSize),
    titleSize: ux(nameSize * 0.75),
    flagHeight: ux(flagHeight),
    flagFont: ux(Math.max(flagFont, 1.6)),
    flagMinWidth: ux(flagMinWidth),
    markerCol: ux(markerCol),
    nameGap: ux(nameGap),
    rowGap: ux(rowGap),
    rowGapUnits: rowGap,
    markerColUnits: markerCol,
    lineWidth: ux(1),
    stopGap: ux(stopGap),
  } as const;
};

/**
 * Shared CSS lengths for horizontal strip diagrams.
 * `labelPlacement` shifts the route centreline when names sit below / alternate.
 */
export const horizontalDiagramMetrics = (
  labelPlacement: "above" | "below" | "alternate" = "above",
) => {
  const tickProtrude = LINE_DIAGRAM.stationTick;
  const tickHeightUnits = 1 + tickProtrude * 2;
  const ringOuter = LINE_DIAGRAM.interchange.outerDiameter;
  const ringStroke = LINE_DIAGRAM.interchange.stroke;
  const nameSize = HORIZONTAL_NAME_SIZE_UNITS;
  const capHeight = nameSize * DIAGRAM_CAP_HEIGHT_RATIO;
  const { top, text, bottom } = LINE_DIAGRAM.layout.flagPaddingCh;
  const flagHeight = capHeight * (top + text + bottom);
  const flagFont = Math.max(
    (capHeight * text) / DIAGRAM_CAP_HEIGHT_RATIO,
    1,
  );
  const flagMinWidth = Math.max(8, capHeight * 4);
  const nameGap = 0.75;
  const nameBand = nameSize * 2.35;
  const markerBand = Math.max(ringOuter, tickHeightUnits);
  const colWidth = Math.max(ringOuter + 10, flagMinWidth + 4, 12);
  const aboveBand =
    labelPlacement === "below" ? 0 : nameBand + nameGap;
  const lineTop = aboveBand + markerBand / 2 - 0.5;
  const flagClearance = LINE_DIAGRAM.layout.nameBelowLine;

  return {
    tickWidth: ux(1),
    tickHeight: ux(tickHeightUnits),
    ringOuter: ux(ringOuter),
    ringStroke: ux(ringStroke),
    nameSize: ux(nameSize),
    titleSize: ux(nameSize * 0.9),
    flagHeight: ux(flagHeight),
    flagFont: ux(flagFont),
    flagMinWidth: ux(flagMinWidth),
    nameGap: ux(nameGap),
    nameBand: ux(nameBand),
    markerBand: ux(markerBand),
    colWidth: ux(colWidth),
    lineTop: ux(lineTop),
    flagClearance: ux(flagClearance),
    lineWidth: ux(1),
    colWidthUnits: colWidth,
  } as const;
};

/** Outer radius of an interchange ring (centre → outer edge). */
export const interchangeOuterRadius = (x: DiagramUnit): number =>
  scale(x, LINE_DIAGRAM.interchange.outerDiameter / 2);

/** Inner (hole) radius of an interchange ring. */
export const interchangeInnerRadius = (x: DiagramUnit): number =>
  scale(x, LINE_DIAGRAM.interchange.innerDiameter / 2);

/** Stroke width of an interchange ring. */
export const interchangeStroke = (x: DiagramUnit): number =>
  scale(x, LINE_DIAGRAM.interchange.stroke);

/** Centreline radius for a 90° bend when the innermost curve is R3x. */
export const bendCenterlineRadius = (x: DiagramUnit): number =>
  scale(x, LINE_DIAGRAM.innerCurveRadius + LINE_DIAGRAM.lineThickness / 2);

/**
 * SVG path for a station tick centred on (cx, cy), for a horizontal line.
 * Tick is a 0.66x square sitting on the line (top-aligned to line top in diagrams;
 * here centred on the line centre for map use).
 */
export const stationTickRect = (
  cx: number,
  cy: number,
  x: DiagramUnit,
): { x: number; y: number; width: number; height: number } => {
  const size = scale(x, LINE_DIAGRAM.stationTick);
  return { x: cx - size / 2, y: cy - size / 2, width: size, height: size };
};

/**
 * Polygon points for a continuation arrow pointing +X, stem centred on y.
 * Geometry from §7: total height 4x, 45° arms, tip forms 90°.
 */
export const continuationArrowPoints = (
  tipX: number,
  cy: number,
  x: DiagramUnit,
  direction: 1 | -1 = 1,
): string => {
  const tipExtent = scale(x, 2);
  const back = tipX - direction * tipExtent;
  const topOuter = cy - 2 * x;
  const botOuter = cy + 2 * x;
  const halfStem = scale(x, LINE_DIAGRAM.arrow.stem) / 2;
  const innerBack = tipX - direction * (tipExtent - x);
  return [
    [tipX, cy],
    [back, topOuter],
    [innerBack, cy - halfStem],
    [innerBack, cy + halfStem],
    [back, botOuter],
  ]
    .map(([px, py]) => `${px},${py}`)
    .join(" ");
};

/** Path `d` for a 90° centreline bend (quarter circle), convex toward +X/+Y. */
export const bend90Path = (
  startX: number,
  startY: number,
  x: DiagramUnit,
  turn: "down-right" | "up-right" | "down-left" | "up-left" = "down-right",
): string => {
  const r = bendCenterlineRadius(x);
  const map = {
    "down-right": { dx: r, dy: r },
    "up-right": { dx: r, dy: -r },
    "down-left": { dx: -r, dy: r },
    "up-left": { dx: -r, dy: -r },
  } as const;
  const { dx, dy } = map[turn];
  const endX = startX + dx;
  const endY = startY + dy;
  const sweepFlag =
    turn === "down-right" || turn === "up-left" ? 1 : 0;
  return `M ${startX} ${startY} A ${r} ${r} 0 0 ${sweepFlag} ${endX} ${endY}`;
};

