const recipesByStationId = new Map<string, StationLabelRecipe>();
const recipesByNameKey = new Map<string, StationLabelRecipe>();

for (const recipe of STATION_LABEL_RECIPES) {
  if (recipe.stationId) {
    recipesByStationId.set(recipe.stationId, recipe);
  }
  for (const id of recipe.stationIds ?? []) {
    recipesByStationId.set(id, recipe);
  }
  if (recipe.nameKey && !recipesByNameKey.has(recipe.nameKey)) {
    recipesByNameKey.set(recipe.nameKey, recipe);
  }
}

const recipeToOverride = (
  recipe: StationLabelRecipe,
): HorizontalStationLabelOverride => ({
  lines: recipe.lines,
  abbreviated: recipe.abbreviated,
});

/**
 * Resolve a horizontal label recipe by station id (preferred) or raw name.
 */
export const getStationLabelRecipe = (
  rawNameOrId: string,
  stationId?: string,
): StationLabelRecipe | undefined => {
  if (stationId) {
    const byId = recipesByStationId.get(stationId);
    if (byId) return byId;
  }
  const asId = recipesByStationId.get(rawNameOrId);
  if (asId) return asId;

  const displayName = formatStationName(rawNameOrId);
  return recipesByNameKey.get(stationLabelKey(displayName));
};

/**
 * Horizontal-diagram label override for a station, if any.
 * Accepts raw TfL names — `formatStationName` is applied first.
 * Pass `stationId` when available so ID-keyed recipes win.
 */
export const getHorizontalStationLabelOverride = (
  rawName: string,
  stationId?: string,
): HorizontalStationLabelOverride | undefined => {
  const recipe = getStationLabelRecipe(rawName, stationId);
  return recipe ? recipeToOverride(recipe) : undefined;
};

/** @deprecated Prefer `getHorizontalStationLabelOverride`. */
export const getHorizontalForcedLineBreak = (
  rawName: string,
): readonly string[] | undefined =>
  getHorizontalStationLabelOverride(rawName)?.lines;

/** @deprecated Prefer `STATION_LABEL_RECIPES` / `getStationLabelRecipe`. */
export const HORIZONTAL_STATION_LABEL_OVERRIDES: Readonly<
  Record<string, HorizontalStationLabelOverride>
> = Object.fromEntries(
  [...recipesByNameKey.entries()].map(([key, recipe]) => [
    key,
    recipeToOverride(recipe),
  ]),
);

/**
 * Render-ready strip models and pure preparation helpers.
 *
 * Atoms (`StraightStrip`, `BranchStrip`) only render these contracts.
 * TfL-aware adjacency, closures, colours, and label recipes live in
 * `LineStrip` / callers that invoke these helpers.
 */

import type {
  DiagramSegment,
  DiagramSegmentState,
  DiagramStation,
} from "./diagram-station";
import { getHorizontalStationLabelOverride } from "./horizontal-station-labels";
import type { LineSchematic } from "./line-schematic";

export type StripSegmentState = DiagramSegmentState;

/** Atomic straight-strip station: display fields only, no TfL lookup. */
export type StraightStripStation = DiagramStation & {
  /**
   * Editorial visual line breaks prepared by the molecule.
   * When omitted, StationName uses a single canonical line.
   */
  labelLines?: readonly string[];
};

export type StripLabelPlacement = "above" | "below" | "alternate";

export type PreparedStraightStrip = {
  stations: StraightStripStation[];
  segmentStates: StripSegmentState[];
  stationOutOfUse: boolean[];
};

export type BranchStripLabelMap = Readonly<
  Record<string, readonly string[] | undefined>
>;

export type PreparedBranchStrip = {
  schematic: LineSchematic;
  /** Per schematic node id → editorial visual lines. */
  nodeLabelLines: BranchStripLabelMap;
  /** Optional edge overrides keyed `"fromId→toId"`. */
  segmentStates?: Readonly<Record<string, StripSegmentState>>;
};

const segmentKey = (fromId: string, toId: string) => `${fromId}→${toId}`;

export const buildSegmentStateMap = (
  stations: readonly Pick<DiagramStation, "id">[],
  segments: readonly DiagramSegment[] | undefined,
): StripSegmentState[] => {
  const override = new Map<string, StripSegmentState>();
  for (const segment of segments ?? []) {
    override.set(
      segmentKey(segment.fromStationId, segment.toStationId),
      segment.state,
    );
  }
  const states: StripSegmentState[] = [];
  for (let i = 0; i < stations.length - 1; i += 1) {
    const from = stations[i]!;
    const to = stations[i + 1]!;
    states.push(override.get(segmentKey(from.id, to.id)) ?? "normal");
  }
  return states;
};

/** True when station index touches an out-of-use segment (legacy / touch rule). */
export const isStationOutOfUse = (
  index: number,
  segmentStates: readonly StripSegmentState[],
): boolean => {
  const leftClosed =
    index > 0 && segmentStates[index - 1] === "out-of-use";
  const rightClosed =
    index < segmentStates.length && segmentStates[index] === "out-of-use";
  return leftClosed || rightClosed;
};

/**
 * Derive which stations to grey from segment states.
 *
 * A station is out-of-use only when **every** adjacent spine segment is
 * out-of-use:
 * - Queen’s Park (one open side + one closed) → stays open
 * - Harrow & Wealdstone terminal (only segment closed) → closed
 * - Interiors of a closed stretch (both sides closed) → closed
 * - Full-line mute → every station closed
 */
export const stationOutOfUseFromSegments = (
  stationCount: number,
  segmentStates: readonly StripSegmentState[],
): boolean[] => {
  const out = new Array(stationCount).fill(false);
  if (stationCount === 0) return out;

  for (let i = 0; i < stationCount; i += 1) {
    const hasLeft = i > 0;
    const hasRight = i < segmentStates.length;
    if (!hasLeft && !hasRight) continue;

    const leftClosed = hasLeft && segmentStates[i - 1] === "out-of-use";
    const rightClosed = hasRight && segmentStates[i] === "out-of-use";

    if (hasLeft && hasRight) {
      out[i] = leftClosed && rightClosed;
    } else if (hasLeft) {
      out[i] = leftClosed;
    } else {
      out[i] = rightClosed;
    }
  }

  return out;
};

/** Apply strip label recipes to domain stations (TfL-aware preparation). */
export const applyStripLabelRecipes = (
  stations: readonly DiagramStation[],
): StraightStripStation[] =>
  stations.map((station) => {
    const recipe = getHorizontalStationLabelOverride(station.name, station.id);
    if (!recipe?.lines) return { ...station };
    return { ...station, labelLines: recipe.lines };
  });

/**
 * Prepare a straight-strip render model from domain stations + optional
 * closure segments / explicit out-of-use ids.
 */
export const prepareStraightStrip = (
  stations: readonly DiagramStation[],
  options: {
    segments?: readonly DiagramSegment[];
    stationOutOfUseIds?: readonly string[];
    /** When false, skip editorial recipes (caller already set labelLines). */
    applyLabelRecipes?: boolean;
  } = {},
): PreparedStraightStrip => {
  const withLabels =
    options.applyLabelRecipes === false
      ? stations.map((s) => ({ ...s }) as StraightStripStation)
      : applyStripLabelRecipes(stations);

  const segmentStates = buildSegmentStateMap(withLabels, options.segments);
  const stationOutOfUse =
    options.stationOutOfUseIds != null
      ? withLabels.map((s) => options.stationOutOfUseIds!.includes(s.id))
      : stationOutOfUseFromSegments(withLabels.length, segmentStates);

  return { stations: withLabels, segmentStates, stationOutOfUse };
};

/** Apply strip label recipes to every schematic node (by node id). */
export const prepareBranchStripLabels = (
  schematic: LineSchematic,
): BranchStripLabelMap => {
  const map: Record<string, readonly string[] | undefined> = {};
  for (const node of schematic.nodes) {
    const recipe = getHorizontalStationLabelOverride(
      node.name,
      node.stationKey ?? node.id,
    );
    map[node.id] = recipe?.lines;
  }
  return map;
};

export const prepareBranchStrip = (
  schematic: LineSchematic,
  options: {
    segmentStates?: Readonly<Record<string, StripSegmentState>>;
    applyLabelRecipes?: boolean;
    nodeLabelLines?: BranchStripLabelMap;
  } = {},
): PreparedBranchStrip => ({
  schematic,
  nodeLabelLines:
    options.nodeLabelLines ??
    (options.applyLabelRecipes === false
      ? {}
      : prepareBranchStripLabels(schematic)),
  segmentStates: options.segmentStates,
});

export const branchSegmentKey = segmentKey;

import { getLineColor } from "tfl-ts";
import {
  formatStationName,
  isLikelyInterchange,
  type DiagramConnection,
  type DiagramStation,
} from "@/lib/tfl/diagram-station";

type StopLike = {
  id?: string | null;
  name?: string | null;
  lines?: { id?: string | null; name?: string | null }[] | null;
  modes?: string[] | null;
};

const DARK_TEXT_LINES = new Set([
  "circle",
  "hammersmith-city",
  "waterloo-city",
]);

/** Classic Underground line IDs (flag group 1 in §9). */
const UNDERGROUND_LINE_IDS = new Set([
  "bakerloo",
  "central",
  "circle",
  "district",
  "hammersmith-city",
  "jubilee",
  "metropolitan",
  "northern",
  "piccadilly",
  "victoria",
  "waterloo-city",
]);

/**
 * National Rail / TOC identifiers that TfL attaches as connecting "lines".
 * Default diagram behaviour sets `nationalRail: true` (pictogram beside the
 * name) rather than a §9 text flag.
 */
export const NATIONAL_RAIL_LINE_IDS = new Set([
  "national-rail",
  "nationalrail",
  "c2c",
  "greater-anglia",
  "thameslink",
  "southern",
  "southeastern",
  "south-western-railway",
  "southwestern-railway",
  "great-northern",
  "great-western",
  "gatwick-express",
  "heathrow-express",
  "heathrow-connect",
  "london-northwestern-railway",
  "chiltern-railways",
  "east-midlands-railway",
  "cross-country",
  "scotrail",
  "tfl-rail",
]);

const TFL_MODE_LINE_IDS = new Set([
  "dlr",
  "elizabeth",
  "elizabeth-line",
  "tram",
  "london-cable-car",
  "emirates-airline",
  "liberty",
  "lioness",
  "mildmay",
  "suffragette",
  "weaver",
  "windrush",
  "overground",
]);

export type NationalRailFlagMode = "collapse" | "operators";

export type DiagramStationMapOptions = {
  /**
   * How to treat National Rail / TOC connections.
   * - `collapse` (default): set `nationalRail: true` on the station (pictogram);
   *   do not emit a §9 text flag
   * - `operators`: keep each TOC name as a connection flag (still drops bus IDs)
   */
  nationalRailFlags?: NationalRailFlagMode;
};

const isNationalRailId = (lineId: string): boolean => {
  const id = lineId.toLowerCase();
  if (NATIONAL_RAIL_LINE_IDS.has(id)) return true;
  if (id.includes("national-rail") || id.includes("nationalrail")) return true;
  // Heuristic: many TOCs appear as mode national-rail with custom ids
  return false;
};

const connectionGroup = (
  lineId: string,
): "underground" | "tfl-mode" | "national-rail" | "other" => {
  if (UNDERGROUND_LINE_IDS.has(lineId)) return "underground";
  if (isNationalRailId(lineId)) return "national-rail";
  if (TFL_MODE_LINE_IDS.has(lineId)) return "tfl-mode";
  return "other";
};

const GROUP_ORDER: Record<ReturnType<typeof connectionGroup>, number> = {
  underground: 0,
  "tfl-mode": 1,
  other: 2,
  "national-rail": 3,
};

/** §9 flag order: Tube α → other TfL modes α → National Rail. */
export const sortDiagramConnections = (
  connections: DiagramConnection[],
): DiagramConnection[] =>
  [...connections].sort((a, b) => {
    const ga = GROUP_ORDER[connectionGroup(a.id)];
    const gb = GROUP_ORDER[connectionGroup(b.id)];
    if (ga !== gb) return ga - gb;
    return a.name.localeCompare(b.name, "en-GB");
  });

/**
 * Collapse TOC connections into National Rail metadata + Tube/TfL flags.
 * Drops unknown / bus IDs (`other`). National Rail is never a text flag —
 * callers use `nationalRail` for the pictogram beside the name.
 */
export const normalizeDiagramConnections = (
  connections: DiagramConnection[],
  mode: NationalRailFlagMode = "collapse",
): { connections: DiagramConnection[]; nationalRail: boolean } => {
  let nationalRail = false;
  const kept: DiagramConnection[] = [];

  for (const connection of connections) {
    const group = connectionGroup(connection.id);
    if (group === "other") continue;
    if (group === "national-rail") {
      nationalRail = true;
      if (mode === "operators") kept.push(connection);
      continue;
    }
    kept.push(connection);
  }

  if (mode === "operators") {
    return {
      connections: sortDiagramConnections(kept),
      nationalRail,
    };
  }

  return {
    connections: sortDiagramConnections(kept),
    nationalRail,
  };
};

/** Map a TfL MatchedStop / StopPoint into diagram station props. */
export const toDiagramStation = (
  stop: StopLike,
  hostLineId?: string,
  options?: DiagramStationMapOptions,
): DiagramStation => {
  const id = stop.id ?? stop.name ?? cryptoRandomId();
  const host = hostLineId?.toLowerCase();
  const nationalRailFlags = options?.nationalRailFlags ?? "collapse";

  const rawConnections =
    stop.lines
      ?.filter((l) => l.id && l.id.toLowerCase() !== host)
      .map((l) => {
        const lineId = (l.id ?? "").toLowerCase();
        const color = getLineColor(lineId);
        return {
          id: lineId,
          name: l.name ?? lineId,
          color: color.hex,
          darkText: DARK_TEXT_LINES.has(lineId),
        };
      }) ?? [];

  const { connections, nationalRail } = normalizeDiagramConnections(
    rawConnections,
    nationalRailFlags,
  );

  return {
    id,
    name: stop.name ?? id,
    interchange: isLikelyInterchange(stop),
    connections: connections.length > 0 ? connections : undefined,
    nationalRail: nationalRail || undefined,
  };
};

/** Slice stations from `fromId` to `toId` (inclusive). Returns null if not found in order. */
export const sliceJourney = (
  stations: DiagramStation[],
  fromId: string,
  toId: string,
): {
  from: DiagramStation;
  to: DiagramStation;
  intermediates: DiagramStation[];
} | null => {
  const fromIndex = stations.findIndex((s) => s.id === fromId);
  const toIndex = stations.findIndex((s) => s.id === toId);
  if (fromIndex < 0 || toIndex < 0) return null;

  const [start, end] =
    fromIndex <= toIndex ? [fromIndex, toIndex] : [toIndex, fromIndex];
  const slice = stations.slice(start, end + 1);
  if (slice.length < 2) return null;

  const forward = fromIndex <= toIndex;
  const ordered = forward ? slice : [...slice].reverse();
  return {
    from: ordered[0]!,
    to: ordered[ordered.length - 1]!,
    intermediates: ordered.slice(1, -1),
  };
};

export { formatStationName, isLikelyInterchange };

const cryptoRandomId = (): string =>
  `stop-${Math.random().toString(36).slice(2, 10)}`;

/**
 * Lane/position schematic model for branched tube diagrams.
 * Inspired by Wikipedia BS-route maps: every stop sits on a grid of
 * main-axis ordinal (`pos`) × cross-axis track (`lane`).
 *
 * Layout is orientation-specific: do not assume rotating a horizontal
 * schematic yields a correct vertical TfL diagram. `lane` is a visual
 * branch instruction, not inferred topology.
 */

export type SchematicNodeKind = "stop" | "interchange" | "terminus";

export type SchematicOrientationHint = "horizontal" | "vertical";

export type SchematicNode = {
  /**
   * Unique render id within one schematic (e.g. `euston-bank`, `euston-cx`).
   * Edges reference these ids.
   */
  id: string;
  /**
   * Shared station identity across duplicate render nodes (e.g. both Eustons
   * use `stationKey: "euston"`). Defaults to `id` when omitted.
   */
  stationKey?: string;
  /** Raw name — StationName canonicalises copy / find. */
  name: string;
  /** Cross-axis visual lane / branch instruction. */
  lane: number;
  /** Main-axis grid column (horizontal) / row (vertical). */
  pos: number;
  kind?: SchematicNodeKind;
  branchIds?: readonly string[];
};

export type SchematicEdge = {
  from: string;
  to: string;
  branchId?: string;
  state?: "normal" | "out-of-use";
};

export type SchematicBranchMeta = {
  id: string;
  name: string;
};

export type LineSchematic = {
  lineId: string;
  lineName: string;
  /** Which presentation this lane/pos map is authored for. */
  orientation: SchematicOrientationHint;
  branches: readonly SchematicBranchMeta[];
  nodes: readonly SchematicNode[];
  edges: readonly SchematicEdge[];
};

export type SchematicBounds = {
  minLane: number;
  maxLane: number;
  minPos: number;
  maxPos: number;
};

export const schematicStationKey = (node: SchematicNode): string =>
  node.stationKey ?? node.id;

export const schematicNodeMap = (
  schematic: LineSchematic,
): ReadonlyMap<string, SchematicNode> =>
  new Map(schematic.nodes.map((node) => [node.id, node]));

export const schematicBounds = (schematic: LineSchematic): SchematicBounds => {
  if (schematic.nodes.length === 0) {
    return { minLane: 0, maxLane: 0, minPos: 0, maxPos: 0 };
  }
  let minLane = Infinity;
  let maxLane = -Infinity;
  let minPos = Infinity;
  let maxPos = -Infinity;
  for (const node of schematic.nodes) {
    if (node.lane < minLane) minLane = node.lane;
    if (node.lane > maxLane) maxLane = node.lane;
    if (node.pos < minPos) minPos = node.pos;
    if (node.pos > maxPos) maxPos = node.pos;
  }
  return { minLane, maxLane, minPos, maxPos };
};

export type SchematicValidationIssue = {
  code:
    | "duplicate-id"
    | "duplicate-lane-pos"
    | "missing-edge-endpoint"
    | "self-edge";
  message: string;
};

/**
 * Structural checks for hand-authored schematics.
 * Throws in development when issues are found (call from fixtures).
 * Multiple nodes may share `stationKey`; `id` and `lane+pos` must be unique.
 */
export const validateSchematic = (
  schematic: LineSchematic,
): SchematicValidationIssue[] => {
  const issues: SchematicValidationIssue[] = [];
  const byId = new Map<string, SchematicNode>();
  const lanePos = new Map<string, string>();

  for (const node of schematic.nodes) {
    if (byId.has(node.id)) {
      issues.push({
        code: "duplicate-id",
        message: `Duplicate node id "${node.id}"`,
      });
      continue;
    }
    byId.set(node.id, node);

    const key = `${node.lane}:${node.pos}`;
    const existing = lanePos.get(key);
    if (existing) {
      issues.push({
        code: "duplicate-lane-pos",
        message: `Nodes "${existing}" and "${node.id}" share lane ${node.lane} pos ${node.pos}`,
      });
    } else {
      lanePos.set(key, node.id);
    }
  }

  for (const edge of schematic.edges) {
    if (edge.from === edge.to) {
      issues.push({
        code: "self-edge",
        message: `Self-edge on "${edge.from}"`,
      });
    }
    if (!byId.has(edge.from)) {
      issues.push({
        code: "missing-edge-endpoint",
        message: `Edge from unknown node "${edge.from}"`,
      });
    }
    if (!byId.has(edge.to)) {
      issues.push({
        code: "missing-edge-endpoint",
        message: `Edge to unknown node "${edge.to}"`,
      });
    }
  }

  return issues;
};

export const assertValidSchematic = (schematic: LineSchematic): void => {
  const issues = validateSchematic(schematic);
  if (issues.length === 0) return;
  const detail = issues.map((i) => `- ${i.message}`).join("\n");
  throw new Error(
    `Invalid LineSchematic "${schematic.lineId}" (${schematic.orientation}):\n${detail}`,
  );
};

import {
  schematicBounds,
  schematicNodeMap,
  schematicStationKey,
  type LineSchematic,
  type SchematicEdge,
  type SchematicNode,
} from "@/lib/tfl/line-schematic";

export type SchematicOrientation = "horizontal" | "vertical";

/** Screen-space direction of the route through a node (for tick/terminus). */
export type SchematicTrackAxis = "x" | "y";

export type SchematicLayoutPoint = {
  id: string;
  stationKey: string;
  name: string;
  x: number;
  y: number;
  lane: number;
  pos: number;
  kind: NonNullable<SchematicNode["kind"]>;
  branchIds?: readonly string[];
  /**
   * Local track tangent at this node (tick/terminus must be ⊥ to this).
   * Bezier ends use the diagram main axis — not the chord’s dominant axis.
   */
  trackAxis: SchematicTrackAxis;
};

export type SchematicLayoutEdge = {
  from: string;
  to: string;
  branchId?: string;
  state: NonNullable<SchematicEdge["state"]>;
  path: string;
};

export type SchematicLayout = {
  width: number;
  height: number;
  orientation: SchematicOrientation;
  points: SchematicLayoutPoint[];
  edges: SchematicLayoutEdge[];
  mainPitch: number;
  lanePitch: number;
  padding: number;
  minLane: number;
  maxLane: number;
};

export type SchematicLayoutOptions = {
  orientation?: SchematicOrientation;
  /** Spacing along the main axis (pos). */
  mainPitch?: number;
  /** Spacing across lanes. */
  lanePitch?: number;
  padding?: number;
  /** Absolute diagram unit x for curve radii. */
  x?: number;
  cornerRadius?: number;
};

const DEFAULT_MAIN_PITCH = 72;
const DEFAULT_LANE_PITCH = 64;
const DEFAULT_PADDING = 48;

/**
 * Smooth lane-change connector: cubic Bezier with end tangents along the
 * diagram main axis (corridor flow).
 *
 * Handle length targets ~¾ of `mainPitch`, capped by both the main-axis run
 * and the cross-axis jump so multi-lane joins (e.g. Edgware → Camden) stay
 * round without overshooting.
 *
 * Spurs need ≈ ≥ 1 station of main-axis span or they collapse to a straight
 * stub; fixtures should offset spur `pos` accordingly.
 */
export const bezierLanePath = (
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  mainAxis: "x" | "y" = "x",
  /** Station gap along the main axis — preferred handle length scales from this. */
  mainPitch = DEFAULT_MAIN_PITCH,
): string => {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const absDx = Math.abs(dx);
  const absDy = Math.abs(dy);
  if (absDx < 0.5 && absDy < 0.5) {
    return `M ${x0} ${y0}`;
  }
  // Pure main-axis (same lane) — straight.
  const mainDelta = mainAxis === "x" ? absDx : absDy;
  const crossDelta = mainAxis === "x" ? absDy : absDx;
  if (crossDelta < 0.5) {
    return `M ${x0} ${y0} L ${x1} ${y1}`;
  }
  // Pure cross-axis (same pos) — no room for a Bezier; keep a straight stub.
  // Prefer offsetting spur `pos` in fixtures instead of inventing a bulge.
  if (mainDelta < 0.5) {
    return `M ${x0} ${y0} L ${x1} ${y1}`;
  }

  const handleTarget = mainPitch * 0.75;
  // Keep handles under half the main run so control points never cross
  // (crossed handles make Camden/Mornington joins look kinked).
  const handle = Math.min(
    handleTarget,
    mainDelta * 0.4,
    crossDelta * 0.85,
  );

  if (mainAxis === "x") {
    const sx = Math.sign(dx);
    return `M ${x0} ${y0} C ${x0 + sx * handle} ${y0}, ${x1 - sx * handle} ${y1}, ${x1} ${y1}`;
  }
  const sy = Math.sign(dy);
  return `M ${x0} ${y0} C ${x0} ${y0 + sy * handle}, ${x1} ${y1 - sy * handle}, ${x1} ${y1}`;
};

/**
 * Orthogonal connector with a quarter-circle corner when lanes differ.
 * Travels main-axis first, then cross-axis. Prefer `bezierLanePath` for
 * flowing corridor diagrams.
 */
export const orthogonalRoundedPath = (
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  radius: number,
  mainAxis: "x" | "y" = "x",
): string => {
  const dx = x1 - x0;
  const dy = y1 - y0;
  if (Math.abs(dx) < 0.5 || Math.abs(dy) < 0.5) {
    return `M ${x0} ${y0} L ${x1} ${y1}`;
  }

  const absDx = Math.abs(dx);
  const absDy = Math.abs(dy);
  // Keep a true quarter turn — leave a straight run into the bend.
  const r = Math.min(radius, absDx * 0.5, absDy * 0.5);
  if (r < 0.5) {
    return mainAxis === "x"
      ? `M ${x0} ${y0} L ${x1} ${y0} L ${x1} ${y1}`
      : `M ${x0} ${y0} L ${x0} ${y1} L ${x1} ${y1}`;
  }

  const sx = Math.sign(dx);
  const sy = Math.sign(dy);

  if (mainAxis === "x") {
    // Run along x to the bend, arc onto the target x, finish along y.
    const bendX = x1 - sx * r;
    const bendY = y0 + sy * r;
    // SVG sweep: 1 = clockwise. Right-then-down / left-then-up → clockwise.
    const sweep = sx * sy > 0 ? 1 : 0;
    return [
      `M ${x0} ${y0}`,
      `L ${bendX} ${y0}`,
      `A ${r} ${r} 0 0 ${sweep} ${x1} ${bendY}`,
      `L ${x1} ${y1}`,
    ].join(" ");
  }

  // Run along y to the bend, arc onto the target y, finish along x.
  const bendY = y1 - sy * r;
  const bendX = x0 + sx * r;
  const sweep = sx * sy < 0 ? 1 : 0;
  return [
    `M ${x0} ${y0}`,
    `L ${x0} ${bendY}`,
    `A ${r} ${r} 0 0 ${sweep} ${bendX} ${y1}`,
    `L ${x1} ${y1}`,
  ].join(" ");
};

/**
 * Local track tangent at a node — used so ticks stay ⊥ to the line.
 *
 * `bezierLanePath` ends are always tangent to the diagram main axis, so a
 * Mill Hill Bezier spur still leaves the terminus along the corridor, not
 * along the cross-axis chord. Scoring by total |dx|/|dy| wrongly flipped
 * that spur to a parallel dash.
 *
 * Rules:
 * - same-lane edge → main axis
 * - lane-change with main-axis span (Bezier) → main axis (end tangents)
 * - pure cross stub (same pos) → cross axis only
 */
const localTrackTangent = (
  id: string,
  xy: Map<string, { x: number; y: number }>,
  edges: readonly SchematicEdge[],
  orientation: SchematicOrientation,
  laneById: ReadonlyMap<string, number>,
): SchematicTrackAxis => {
  const mainAxis: SchematicTrackAxis =
    orientation === "horizontal" ? "x" : "y";
  const crossAxis: SchematicTrackAxis = mainAxis === "x" ? "y" : "x";

  let mainTangent = 0;
  let crossOnly = 0;

  for (const edge of edges) {
    if (edge.from !== id && edge.to !== id) continue;
    const a = xy.get(edge.from);
    const b = xy.get(edge.to);
    if (!a || !b) continue;
    const otherId = edge.from === id ? edge.to : edge.from;
    const sameLane = laneById.get(id) === laneById.get(otherId);
    const dx = Math.abs(b.x - a.x);
    const dy = Math.abs(b.y - a.y);
    const mainDelta = mainAxis === "x" ? dx : dy;
    const crossDelta = mainAxis === "x" ? dy : dx;

    if (sameLane || mainDelta >= 0.5) {
      // Corridor run or Bezier lane-change — tangent at the node is main-axis.
      mainTangent += 1;
    } else if (crossDelta >= 0.5) {
      crossOnly += 1;
    }
  }

  if (mainTangent > 0) return mainAxis;
  if (crossOnly > 0) return crossAxis;
  return mainAxis;
};

/**
 * Place schematic nodes on a grid and build edge paths.
 * Horizontal: pos → x, lane → y. Vertical swaps axes.
 */
export const layoutLineSchematic = (
  schematic: LineSchematic,
  options: SchematicLayoutOptions = {},
): SchematicLayout => {
  const orientation = options.orientation ?? schematic.orientation;
  const mainPitch = options.mainPitch ?? DEFAULT_MAIN_PITCH;
  const lanePitch = options.lanePitch ?? DEFAULT_LANE_PITCH;
  const padding = options.padding ?? DEFAULT_PADDING;

  const bounds = schematicBounds(schematic);
  const byId = schematicNodeMap(schematic);

  const toXY = (lane: number, pos: number): { x: number; y: number } => {
    const main = padding + (pos - bounds.minPos) * mainPitch;
    const cross = padding + (lane - bounds.minLane) * lanePitch;
    return orientation === "horizontal"
      ? { x: main, y: cross }
      : { x: cross, y: main };
  };

  const xyById = new Map<string, { x: number; y: number }>();
  const laneById = new Map<string, number>();
  for (const node of schematic.nodes) {
    xyById.set(node.id, toXY(node.lane, node.pos));
    laneById.set(node.id, node.lane);
  }

  const points: SchematicLayoutPoint[] = schematic.nodes.map((node) => {
    const { x, y } = xyById.get(node.id)!;
    return {
      id: node.id,
      stationKey: schematicStationKey(node),
      name: node.name,
      x,
      y,
      lane: node.lane,
      pos: node.pos,
      kind: node.kind ?? "stop",
      branchIds: node.branchIds,
      trackAxis: localTrackTangent(
        node.id,
        xyById,
        schematic.edges,
        orientation,
        laneById,
      ),
    };
  });

  const mainAxis: "x" | "y" = orientation === "horizontal" ? "x" : "y";
  const edges: SchematicLayoutEdge[] = [];
  for (const edge of schematic.edges) {
    const from = byId.get(edge.from);
    const to = byId.get(edge.to);
    if (!from || !to) continue;

    const a = xyById.get(from.id)!;
    const b = xyById.get(to.id)!;
    const sameLane = from.lane === to.lane;
    // Always Bezier for lane changes — orthogonal "staircase" corners read as
    // broken joins at Camden / Mornington / Kennington.
    const path = sameLane
      ? `M ${a.x} ${a.y} L ${b.x} ${b.y}`
      : bezierLanePath(a.x, a.y, b.x, b.y, mainAxis, mainPitch);

    edges.push({
      from: edge.from,
      to: edge.to,
      branchId: edge.branchId,
      state: edge.state ?? "normal",
      path,
    });
  }

  const mainSpan = (bounds.maxPos - bounds.minPos) * mainPitch;
  const laneSpan = (bounds.maxLane - bounds.minLane) * lanePitch;
  const width =
    orientation === "horizontal"
      ? mainSpan + padding * 2
      : laneSpan + padding * 2;
  const height =
    orientation === "horizontal"
      ? laneSpan + padding * 2
      : mainSpan + padding * 2;

  return {
    width,
    height,
    orientation,
    points,
    edges,
    mainPitch,
    lanePitch,
    padding,
    minLane: bounds.minLane,
    maxLane: bounds.maxLane,
  };
};
